group -->\n<!-- wp:list {\"className\":\"sr-icon-list\"} -->\n<ul class=\"wp-block-list sr-icon-list\"><!-- wp:list-item -->\n<li>10+2 from a recognised board (Science preferred; other streams as per INC norms)</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Minimum age 17 years on or before 31 December of the admission year</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What you will study</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Bio-sciences and behavioural sciences</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Fundamentals of nursing and first aid</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Medical-surgical, community health and mental health nursing</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Child health nursing and midwifery</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Clinical practice in our hospital and community postings</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph {\"className\":\"sr-placeholder\"} -->\n<p class=\"sr-placeholder\">Please confirm the approved GNM intake (seats) for the current session.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Career opportunities</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Staff nurse in government and private hospitals</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Community health nurse / public health programmes</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Military Nursing Service, railways and ESIC hospitals</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Nursing tutor (with higher qualifications)</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Further study: Post Basic B.Sc Nursing</li>\n