(24,0,'2026-09-26 21:14:27','2026-09-26 15:44:27','<!-- wp:paragraph {\"className\":\"has-large-font-size\"} -->\n<p class=\"has-large-font-size\">A two-year diploma that trains community health workers in maternal and child health, first aid and primary care.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"align\":\"full\",\"backgroundColor\":\"light\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\",\"wideSize\":\"1200px\"}} -->\n<div class=\"wp-block-group alignfull has-light-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50)\">\n<!-- wp:columns -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-feature sr-icon sr-icon--soft ico-clipboard\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-feature sr-icon sr-icon--soft ico-clipboard\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Key facts</h3>\n<!-- /wp:heading -->\n</div>\n<!-- /wp:group -->\n<!-- wp:table -->\n<figure class=\"wp-block-table\"><table><tbody><tr><td>Level</td><td>Diploma</td></tr><tr><td>Duration</td><td>2 years</td></tr><tr><td>Seats</td><td>30</td></tr><tr><td>Regulated by</td><td>HNRC &amp; INC</td></tr><tr><td>Selection</td><td>Merit based</td></tr><tr><td>Mode</td><td>Full time</td></tr></tbody></table></figure>\n<!-- /wp:table -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-feature sr-icon sr-icon--soft ico-check\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-feature sr-icon sr-icon--soft ico-check\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Eligibility</h3>\n<!-- /wp:heading -->\n</div>\n<!-- /wp:group -->\n<!-- wp:list {\"className\":\"sr-icon-list\"} -->\n<ul class=\"wp-block-list sr-icon-list\"><!-- wp:list-item -->\n<li>10+2 in Arts, Science, Commerce or Health Care Science (Vocational) from a recognised board</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Students who passed 10+2 through the National Institute of Open Schooling (NIOS) may also apply</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Minimum age 17 years on or before 31 December of the admission year</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What you will study</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Community health nursing and health promotion</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Primary health care and first aid</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Child health nursing</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Midwifery and maternal care</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Health centre management</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Career opportunities</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>ANM / health worker at sub-centres and PHCs</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>National health programmes and immunisation drives</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Hospitals, nursing homes and maternity centres</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Further study: GNM and nursing degrees</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"sr-dark sr-cta-band\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"680px\"}} -->\n<div class=\"wp-block-group alignfull sr-dark sr-cta-band\" style=\"padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\">\n<!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Ready to apply?</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">See the admission process, documents required and fees, or send us an enquiry.</p>\n<!-- /wp:paragraph -->\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/admissions/\">Admission process</a></div>\n<!-- /wp:button --><!-- wp:button {\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" href=\"/contact/\">Enquire now</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n</div>\n<!-- /wp:group -->\n','ANM – Auxiliary Nurse Midwifery','','publish','closed','closed','','anm','','','2026-09-26 21:14:27','2026-09-26 15:44:27','',9,'http://localhost:8092/courses/anm/',5,'page','',0),
(25,0,'2026-09-26 19:18:00','2026-09-26 13:48:00','<!-- wp:paragraph -->\n<p>Welcome to the official website of Shri Ram College of Medical Science &amp; Research, Digrota. Admission notices, examination schedules, results and campus news will be posted here.</p>\n<!-- /wp:paragraph -->','Welcome to our new website','','publish','open','open','','welcome-to-our-new-website','','','2026-09-26 19:18:00','2026-09-26 13:48:00','',0,'http://localhost:8092/welcome-to-our-new-website/',0,'post','',0),
(26,0,'2026-09-26 19:18:41','2026-09-26 13:48:41','<!-- wp:group {\"align\":\"full\",\"className\":\"sr-hero\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|70\",\"bottom\":\"calc(var(--wp--preset--spacing--70) + 2rem)\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n<div class=\"wp-block-group alignfull sr-hero\" style=\"padding-top:var(--wp--preset--spacing--70);padding-bottom:calc(var(--wp--preset--spacing--70) + 2rem)\">\n<!-- wp:group {\"layout\":{\"type\":\"constrained\",\"contentSize\":\"820px\",\"justifyContent\":\"left\"}} -->\n<div class=\"wp-block-group\">\n<!-- wp:paragraph {\"className\":\"sr-eyebrow\"} -->\n<p class=\"sr-eyebrow\">Digrota · Satnali · Mahendragarh · Haryana</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":1} -->\n<h1 class=\"wp-block-heading\">Shaping skilled, compassionate nurses and healthcare professionals</h1>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-lead\"} -->\n<p class=\"sr-lead\">Nursing and paramedical programmes approved by the Indian Nursing Council and affiliated to Pt. B.D. Sharma University of Health Sciences, Rohtak, with hands-on clinical training at our own 100-bed hospital.</p>\n<!-- /wp:paragraph -->\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/admissions/\">Apply for Admission</a></div>\n<!-- /wp:button --><!-- wp:button {\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" href=\"/courses/\">Explore Courses</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n<!-- wp:group {\"className\":\"sr-badges\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\"}} -->\n<div class=\"wp-block-group sr-badges\">\n<!-- wp:paragraph -->\n<p>✓ INC Approved</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>✓ HNRC Recognised</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>✓ UHSR Rohtak Affiliated</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>✓ 100-Bed Hospital</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"align\":\"wide\",\"className\":\"sr-stats\"} -->\n<div class=\"wp-block-columns alignwide sr-stats\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:paragraph {\"className\":\"sr-stat__num\"} -->\n<p class=\"sr-stat__num\">100</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-stat__label\"} -->\n<p class=\"sr-stat__label\">Bed attached hospital</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:paragraph {\"className\":\"sr-stat__num\"} -->\n<p class=\"sr-stat__num\">5</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-stat__label\"} -->\n<p class=\"sr-stat__label\">Nursing &amp; paramedical programmes</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:paragraph {\"className\":\"sr-stat__num\"} -->\n<p class=\"sr-stat__num\">170+</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-stat__label\"} -->\n<p class=\"sr-stat__label\">Approved seats every year</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:paragraph {\"className\":\"sr-stat__num\"} -->\n<p class=\"sr-stat__num\">2</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-stat__label\"} -->\n<p class=\"sr-stat__label\">Separate hostels for girls &amp; boys</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\">\n<!-- wp:columns -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">About the college</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Quality nursing education in the heart of rural Haryana</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Shri Ram College of Medical Science &amp; Research at Digrota, Mahendragarh, runs <strong>Shri Ram College of Nursing</strong> and <strong>Shri Ram School of Nursing</strong>. It has been a trusted name in nursing education in the region since 2012.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>We are a private, co-educational institution, approved by the Indian Nursing Council (INC), New Delhi, and the Haryana Nurses &amp; Midwives Council, and affiliated to Pt. B.D. Sharma University of Health Sciences, Rohtak. Students learn in well-equipped classrooms and laboratories and train at our own 100-bed hospital.</p>\n<!-- /wp:paragraph -->\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" href=\"/about/\">More about us</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Why students choose us</h3>\n<!-- /wp:heading -->\n<!-- wp:list {\"className\":\"sr-icon-list\"} -->\n<ul class=\"wp-block-list sr-icon-list\"><!-- wp:list-item -->\n<li>INC-approved, UHSR-affiliated programmes</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Own 100-bed hospital for clinical exposure</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Anatomy, physiology, microbiology &amp; nursing skill labs</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Library with 3,500+ books and nursing journals</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Separate hostels for girls and boys with mess</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>College bus, Wi-Fi campus, gym and sports</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"backgroundColor\":\"light\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n<div class=\"wp-block-group alignfull has-light-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\">\n<!-- wp:group {\"className\":\"sr-section-head is-centered\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-section-head is-centered\">\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"sr-tag\"} -->\n<p class=\"has-text-align-center sr-tag\">Programmes</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Courses we offer</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Degree and diploma programmes in nursing and allied health sciences.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:columns {\"align\":\"wide\"} -->\n<div class=\"wp-block-columns alignwide\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Degree · 4 years</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">B.Sc Nursing</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-meta\"} -->\n<p class=\"sr-meta\">50 seats</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A four-year professional degree that builds a strong foundation in nursing science, anatomy and direct patient care, with extensive hospital practice.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p><a href=\"/courses/bsc-nursing/\">View course details →</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Degree · 2 years</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Post Basic B.Sc Nursing</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-meta\"} -->\n<p class=\"sr-meta\">40 seats</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A two-year degree for registered GNM nurses who want to upgrade to a B.Sc qualification and take on greater clinical and leadership roles.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p><a href=\"/courses/post-basic-bsc-nursing/\">View course details →</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Degree · 3 years</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">B.Sc Paramedical Science</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-meta\"} -->\n<p class=\"sr-meta\">50 seats</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A three-year allied-health degree awarded by Pt. B.D. Sharma UHS, Rohtak, preparing technologists for hospital and diagnostic settings.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p><a href=\"/courses/bsc-paramedical-science/\">View course details →</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n<!-- wp:columns {\"align\":\"wide\"} -->\n<div class=\"wp-block-columns alignwide\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Diploma · 3 years</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">GNM – General Nursing &amp; Midwifery</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-meta\"} -->\n<p class=\"sr-meta\">Seats: as approved</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A diploma programme in general nursing and midwifery, leading to registration as a nurse and midwife with the state council.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p><a href=\"/courses/gnm/\">View course details →</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Diploma · 2 years</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">ANM – Auxiliary Nurse Midwifery</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-meta\"} -->\n<p class=\"sr-meta\">30 seats</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A two-year diploma that trains community health workers in maternal and child health, first aid and primary care.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p><a href=\"/courses/anm/\">View course details →</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/courses/\">Compare all courses</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\">\n<!-- wp:group {\"className\":\"sr-section-head is-centered\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-section-head is-centered\">\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"sr-tag\"} -->\n<p class=\"has-text-align-center sr-tag\">Recognition</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Approvals &amp; affiliations</h2>\n<!-- /wp:heading -->\n</div>\n<!-- /wp:group -->\n<!-- wp:columns {\"align\":\"wide\",\"className\":\"sr-approvals\"} -->\n<div class=\"wp-block-columns alignwide sr-approvals\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Indian Nursing Council</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>INC, New Delhi: national regulator approving our nursing programmes.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Haryana Nurses &amp; Midwives Council</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>HNRC: state recognition and registration of nurses and midwives.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Pt. B.D. Sharma UHS, Rohtak</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Affiliating university for our degree programmes and examinations.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Government of Haryana</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Recognised institution; admissions and fees follow DMER Haryana norms.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"backgroundColor\":\"light\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n<div class=\"wp-block-group alignfull has-light-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\">\n<!-- wp:columns -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Clinical training</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Learn at the bedside in our own 100-bed hospital</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Nursing is learned by doing. Our attached 100-bed hospital gives students supervised clinical experience from the early semesters, alongside community health postings in the surrounding villages.</p>\n<!-- /wp:paragraph -->\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" href=\"/hospital/\">About the hospital</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Campus life</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Everything you need on one campus</h2>\n<!-- /wp:heading -->\n<!-- wp:list {\"className\":\"sr-icon-list\"} -->\n<ul class=\"wp-block-list sr-icon-list\"><!-- wp:list-item -->\n<li>Spacious, fully furnished lecture halls with audio-visual aids</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Well-established laboratories for practical training</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Auditorium for seminars and workshops</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Hygienic canteen, gym and sports complex</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" href=\"/campus-facilities/\">Explore facilities</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\">\n<!-- wp:group {\"className\":\"sr-section-head is-centered\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-section-head is-centered\">\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"sr-tag\"} -->\n<p class=\"has-text-align-center sr-tag\">Admissions</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\">How to join</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Admissions follow the rules of DMER Haryana and Pt. B.D. Sharma UHS, Rohtak.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:columns {\"align\":\"wide\"} -->\n<div class=\"wp-block-columns alignwide\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Step 1</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Check eligibility</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>10+2 with the required subjects and marks, and a minimum age of 17 years by 31 December.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Step 2</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Apply / appear</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>B.Sc courses: register for the UHSR entrance test and counselling. ANM/GNM: merit-based admission.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Step 3</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Choose Shri Ram</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Select Shri Ram College of Nursing, Digrota, during counselling, or contact us for management-quota seats.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Step 4</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Report &amp; enrol</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Report with original documents, pay the fee, and begin your journey in nursing.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/admissions/\">Admission details</a></div>\n<!-- /wp:button --><!-- wp:button {\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" href=\"/fee-structure/\">Fee structure</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"backgroundColor\":\"light\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n<div class=\"wp-block-group alignfull has-light-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\">\n<!-- wp:group {\"className\":\"sr-section-head\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-section-head\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Latest</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Notices &amp; announcements</h2>\n<!-- /wp:heading -->\n</div>\n<!-- /wp:group -->\n<!-- wp:query {\"queryId\":2,\"query\":{\"perPage\":3,\"postType\":\"post\",\"order\":\"desc\",\"orderBy\":\"date\",\"inherit\":false},\"className\":\"sr-notices\"} -->\n<div class=\"wp-block-query sr-notices\">\n<!-- wp:post-template -->\n<!-- wp:post-date {\"fontSize\":\"small\"} /-->\n<!-- wp:post-title {\"isLink\":true,\"level\":3} /-->\n<!-- /wp:post-template -->\n<!-- wp:query-no-results -->\n<!-- wp:paragraph -->\n<p>New notices will appear here.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:query-no-results -->\n</div>\n<!-- /wp:query -->\n<!-- wp:paragraph -->\n<p><a href=\"/notices/\">All notices →</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\">\n<!-- wp:group {\"className\":\"sr-cta\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-cta\" style=\"padding-top:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--40);padding-right:var(--wp--preset--spacing--40)\">\n<!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Begin your career in healthcare</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Talk to our admissions team about courses, eligibility, fees and hostel availability.</p>\n<!-- /wp:paragraph -->\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/contact/\">Contact Admissions</a></div>\n<!-- /wp:button --><!-- wp:button {\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" href=\"/admissions/\">Admission Process</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n','Home','','inherit','closed','closed','','7-revision-v1','','','2026-09-26 19:18:41','2026-09-26 13:48:41','',7,'http://localhost:8092/?p=26',0,'revision','',0),
(27,0,'2026-09-26 19:18:41','2026-09-26 13:48:41','<!-- wp:paragraph {\"className\":\"has-large-font-size\"} -->\n<p class=\"has-large-font-size\">Shri Ram College of Medical Science &amp; Research, Digrota (Mahendragarh), is a private, co-educational institution for nursing and allied health education. Through <strong>Shri Ram College of Nursing</strong> (degree programmes) and <strong>Shri Ram School of Nursing</strong> (diploma programmes), it has served students of Mahendragarh and the surrounding districts since 2012.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The college is approved by the Indian Nursing Council (INC), New Delhi, and the Haryana Nurses &amp; Midwives Council, and is affiliated to Pt. B.D. Sharma University of Health Sciences, Rohtak. The campus has spacious, fully furnished classrooms, well-established laboratories, a comprehensive library and an auditorium. Students also train at our own 100-bed hospital, which gives them the clinical exposure a good nurse needs.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"sr-placeholder\"} -->\n<p class=\"sr-placeholder\">Please confirm the year each institution was established (online sources say 2012 for the group and 2019 for the College of Nursing) and the name of the managing trust or society.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|50\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide\" style=\"margin-top:var(--wp--preset--spacing--50)\">\n<!-- wp:columns -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Our Vision</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>To be a leading centre of nursing and paramedical education in rural Haryana, producing competent, ethical and compassionate healthcare professionals who serve their communities.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Our Mission</h3>\n<!-- /wp:heading -->\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Deliver INC and university-standard education with strong clinical training</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Make quality healthcare education accessible to rural students, especially young women</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Instil empathy, discipline and professional ethics</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Serve the community through health camps and outreach</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph {\"className\":\"sr-placeholder\"} -->\n<p class=\"sr-placeholder\">The Vision and Mission above are drafts written for the website. Please review or replace them with the college\'s official statements.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|50\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide\" style=\"margin-top:var(--wp--preset--spacing--50)\">\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">At a glance</h2>\n<!-- /wp:heading -->\n<!-- wp:table -->\n<figure class=\"wp-block-table\"><table><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Location</td><td>VPO Digrota, Nangal Mala Road, Tehsil Satnali, Distt. Mahendragarh, Haryana – 123024</td></tr><tr><td>Type</td><td>Private (self-financed), co-educational</td></tr><tr><td>Approvals</td><td>Indian Nursing Council (INC), New Delhi; Haryana Nurses &amp; Midwives Council (HNRC)</td></tr><tr><td>Affiliation</td><td>Pt. B.D. Sharma University of Health Sciences, Rohtak</td></tr><tr><td>Programmes</td><td>B.Sc Nursing, Post Basic B.Sc Nursing, B.Sc Paramedical Science, GNM, ANM</td></tr><tr><td>Hospital</td><td>Own 100-bed hospital for clinical training</td></tr><tr><td>Residential</td><td>Separate hostels for girls and boys</td></tr></tbody></table></figure>\n<!-- /wp:table -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|50\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide\" style=\"margin-top:var(--wp--preset--spacing--50)\">\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Leadership</h2>\n<!-- /wp:heading -->\n<!-- wp:columns -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Chairman</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Name to be added</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-placeholder\"} -->\n<p class=\"sr-placeholder\">Chairman\'s photo and message.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Director</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Name to be added</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-placeholder\"} -->\n<p class=\"sr-placeholder\">Director\'s photo and message.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Principal</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Name to be added</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-placeholder\"} -->\n<p class=\"sr-placeholder\">Principal\'s photo, qualifications and message.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n','About the College','','inherit','closed','closed','','8-revision-v1','','','2026-09-26 19:18:41','2026-09-26 13:48:41','',8,'http://localhost:8092/?p=27',0,'revision','',0),
(28,0,'2026-09-26 19:18:41','2026-09-26 13:48:41','<!-- wp:paragraph {\"className\":\"has-large-font-size\"} -->\n<p class=\"has-large-font-size\">We offer degree and diploma programmes in nursing and allied health sciences. All nursing programmes are approved by the Indian Nursing Council and the Haryana Nurses &amp; Midwives Council. Degrees are awarded by Pt. B.D. Sharma University of Health Sciences, Rohtak.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|50\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide\" style=\"margin-top:var(--wp--preset--spacing--50)\">\n<!-- wp:table -->\n<figure class=\"wp-block-table\"><table><thead><tr><th>Programme</th><th>Level</th><th>Duration</th><th>Seats</th><th>Minimum qualification</th></tr></thead><tbody><tr><td><a href=\"/courses/bsc-nursing/\">B.Sc Nursing</a></td><td>UG Degree</td><td>4 years</td><td>50</td><td>10+2 with PCB &amp; English (50%)</td></tr><tr><td><a href=\"/courses/post-basic-bsc-nursing/\">Post Basic B.Sc Nursing</a></td><td>UG Degree</td><td>2 years</td><td>40</td><td>10+2 + GNM, registered nurse &amp; midwife</td></tr><tr><td><a href=\"/courses/bsc-paramedical-science/\">B.Sc Paramedical Science</a></td><td>UG Degree</td><td>3 years</td><td>50</td><td>10+2 with Science</td></tr><tr><td><a href=\"/courses/gnm/\">GNM</a></td><td>Diploma</td><td>3 years</td><td>As approved</td><td>10+2 (any stream)</td></tr><tr><td><a href=\"/courses/anm/\">ANM</a></td><td>Diploma</td><td>2 years</td><td>30</td><td>10+2 (any stream)</td></tr></tbody></table><figcaption class=\"wp-element-caption\">Seat numbers are the approved intake published by the regulators and may change each session.</figcaption></figure>\n<!-- /wp:table -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|50\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide\" style=\"margin-top:var(--wp--preset--spacing--50)\">\n<!-- wp:columns -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Degree · 4 years</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">B.Sc Nursing</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-meta\"} -->\n<p class=\"sr-meta\">50 seats</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A four-year professional degree that builds a strong foundation in nursing science, anatomy and direct patient care, with extensive hospital practice.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p><a href=\"/courses/bsc-nursing/\">View course details →</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Degree · 2 years</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Post Basic B.Sc Nursing</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-meta\"} -->\n<p class=\"sr-meta\">40 seats</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A two-year degree for registered GNM nurses who want to upgrade to a B.Sc qualification and take on greater clinical and leadership roles.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p><a href=\"/courses/post-basic-bsc-nursing/\">View course details →</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Degree · 3 years</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">B.Sc Paramedical Science</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-meta\"} -->\n<p class=\"sr-meta\">50 seats</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A three-year allied-health degree awarded by Pt. B.D. Sharma UHS, Rohtak, preparing technologists for hospital and diagnostic settings.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p><a href=\"/courses/bsc-paramedical-science/\">View course details →</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n<!-- wp:columns -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Diploma · 3 years</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">GNM – General Nursing &amp; Midwifery</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-meta\"} -->\n<p class=\"sr-meta\">Seats: as approved</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A diploma programme in general nursing and midwifery, leading to registration as a nurse and midwife with the state council.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p><a href=\"/courses/gnm/\">View course details →</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Diploma · 2 years</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">ANM – Auxiliary Nurse Midwifery</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-meta\"} -->\n<p class=\"sr-meta\">30 seats</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A two-year diploma that trains community health workers in maternal and child health, first aid and primary care.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p><a href=\"/courses/anm/\">View course details →</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n','Courses','','inherit','closed','closed','','9-revision-v1','','','2026-09-26 19:18:41','2026-09-26 13:48:41','',9,'http://localhost:8092/?p=28',0,'revision','',0),
(29,0,'2026-09-26 19:18:42','2026-09-26 13:48:42','<!-- wp:paragraph {\"className\":\"has-large-font-size\"} -->\n<p class=\"has-large-font-size\">Admissions to Shri Ram College of Nursing and Shri Ram School of Nursing follow the rules of the Indian Nursing Council, the Department of Medical Education &amp; Research (DMER), Haryana, and Pt. B.D. Sharma University of Health Sciences, Rohtak.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Admission process</h2>\n<!-- /wp:heading -->\n\n<!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|50\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide\" style=\"margin-top:var(--wp--preset--spacing--50)\">\n<!-- wp:columns -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">B.Sc Nursing, Post Basic B.Sc &amp; B.Sc Paramedical</h3>\n<!-- /wp:heading -->\n<!-- wp:list {\"ordered\":true} -->\n<ol class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Register for the entrance test / counselling on the UHSR admissions portal (uhsrcetadmissions.in) when it is notified.</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Appear in the entrance test (CET) conducted by Pt. B.D. Sharma UHS, Rohtak.</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Fill in choices during online counselling and select <em>Shri Ram College of Nursing, Digrota, Mahendergarh</em>.</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>On allotment, report to the college with original documents and pay the fee within the given dates.</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list -->\n<!-- wp:paragraph {\"className\":\"sr-meta\"} -->\n<p class=\"sr-meta\">Management-quota seats are filled as per state rules. Contact the college office for details.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">GNM &amp; ANM</h3>\n<!-- /wp:heading -->\n<!-- wp:list {\"ordered\":true} -->\n<ol class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Obtain the application form from the college office (or enquire online).</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Admission is made on merit in the qualifying examination, as per HNRC / Govt. of Haryana norms.</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Attend document verification.</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Pay the fee and complete enrolment.</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Eligibility at a glance</h2>\n<!-- /wp:heading -->\n\n<!-- wp:table -->\n<figure class=\"wp-block-table\"><table><thead><tr><th>Course</th><th>Qualification</th><th>Age</th></tr></thead><tbody><tr><td>B.Sc Nursing</td><td>10+2 with PCB + English, 50% in PCB (relaxation for reserved categories)</td><td>17 years by 31 Dec</td></tr><tr><td>Post Basic B.Sc Nursing</td><td>10+2 + GNM; registered nurse &amp; midwife</td><td>—</td></tr><tr><td>B.Sc Paramedical Science</td><td>10+2 with Science</td><td>As per UHSR</td></tr><tr><td>GNM</td><td>10+2 (as per INC norms)</td><td>17 years by 31 Dec</td></tr><tr><td>ANM</td><td>10+2 in any stream (incl. NIOS / vocational health care)</td><td>17 years by 31 Dec</td></tr></tbody></table></figure>\n<!-- /wp:table -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Documents required</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"className\":\"sr-icon-list\"} -->\n<ul class=\"wp-block-list sr-icon-list\"><!-- wp:list-item -->\n<li>10th and 12th mark sheets and certificates (originals + 2 self-attested copies)</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Entrance test score card and allotment letter (B.Sc courses)</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Haryana domicile / resident certificate (for state-quota seats)</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Caste / category certificate, if applicable</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Aadhaar card and 6 recent passport-size photographs</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Character certificate from the last institution attended</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Migration certificate (for boards outside Haryana)</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Medical fitness certificate</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>GNM certificate and nursing council registration (Post Basic B.Sc only)</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph {\"className\":\"sr-placeholder\"} -->\n<p class=\"sr-placeholder\">Please confirm this document list and add the admission office timings.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Frequently asked questions</h2>\n<!-- /wp:heading -->\n\n<!-- wp:details -->\n<details class=\"wp-block-details\"><summary>Is the college approved by the Indian Nursing Council?</summary><!-- wp:paragraph -->\n<p>Yes. Our nursing programmes are approved by the Indian Nursing Council (INC), New Delhi, and the Haryana Nurses &amp; Midwives Council. See <a href=\"/approvals/\">Approvals &amp; Affiliations</a>.</p>\n<!-- /wp:paragraph --></details>\n<!-- /wp:details -->\n\n<!-- wp:details -->\n<details class=\"wp-block-details\"><summary>Which university awards the degree?</summary><!-- wp:paragraph -->\n<p>Degrees are awarded by Pt. B.D. Sharma University of Health Sciences (UHSR), Rohtak.</p>\n<!-- /wp:paragraph --></details>\n<!-- /wp:details -->\n\n<!-- wp:details -->\n<details class=\"wp-block-details\"><summary>Is hostel accommodation available?</summary><!-- wp:paragraph -->\n<p>Yes. There are separate hostels for girls and boys, with mess facilities and security.</p>\n<!-- /wp:paragraph --></details>\n<!-- /wp:details -->\n\n<!-- wp:details -->\n<details class=\"wp-block-details\"><summary>Is the college co-educational?</summary><!-- wp:paragraph -->\n<p>Yes. Both male and female candidates can apply, subject to the eligibility rules of each course.</p>\n<!-- /wp:paragraph --></details>\n<!-- /wp:details -->\n\n<!-- wp:details -->\n<details class=\"wp-block-details\"><summary>Where do students do their clinical training?</summary><!-- wp:paragraph -->\n<p>At our own 100-bed hospital, plus community health postings. See <a href=\"/hospital/\">Hospital</a>.</p>\n<!-- /wp:paragraph --></details>\n<!-- /wp:details -->\n\n<!-- wp:details -->\n<details class=\"wp-block-details\"><summary>What are the fees?</summary><!-- wp:paragraph -->\n<p>Fees follow the structure notified by the Government of Haryana. See <a href=\"/fee-structure/\">Fee Structure</a>.</p>\n<!-- /wp:paragraph --></details>\n<!-- /wp:details -->\n\n<!-- wp:group {\"className\":\"sr-card\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|50\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\" style=\"margin-top:var(--wp--preset--spacing--50)\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Admission enquiry</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Leave your details and our admissions office will call you back.</p>\n<!-- /wp:paragraph -->\n<!-- wp:shortcode -->\n[contact-form-7 id=\"5\" title=\"Admission Enquiry\"]\n<!-- /wp:shortcode -->\n</div>\n<!-- /wp:group -->\n','Admissions','','inherit','closed','closed','','10-revision-v1','','','2026-09-26 19:18:42','2026-09-26 13:48:42','',10,'http://localhost:8092/?p=29',0,'revision','',0),
(30,0,'2026-09-26 19:18:42','2026-09-26 13:48:42','<!-- wp:paragraph {\"className\":\"has-large-font-size\"} -->\n<p class=\"has-large-font-size\">Fees at Shri Ram College of Nursing follow the fee structure for private colleges notified by the Government of Haryana (Haryana Govt. Gazette, 21 June 2024, Annexure-VI).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"sr-placeholder\"} -->\n<p class=\"sr-placeholder\">Please add the college\'s own fee sheet for the current session (tuition, hostel, mess, transport) for every course, including GNM, ANM and B.Sc Paramedical.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Government-notified fee norms for private colleges</h2>\n<!-- /wp:heading -->\n\n<!-- wp:table -->\n<figure class=\"wp-block-table\"><table><thead><tr><th>Fee head</th><th>B.Sc &amp; Post Basic B.Sc Nursing (per year)</th></tr></thead><tbody><tr><td>Tuition fee (incl. development charges)</td><td>₹60,000, with an annual increase of 5%</td></tr><tr><td>Library fee</td><td>₹3,000</td></tr><tr><td>Sports &amp; medical charges</td><td>₹2,000</td></tr><tr><td>Internet charges</td><td>₹1,000</td></tr><tr><td>Examination &amp; university charges</td><td>As actual</td></tr><tr><td>Hostel fee</td><td>Not more than ₹60,000 or actual, whichever is less (no charge for fan &amp; lighting)</td></tr><tr><td>Mess charges</td><td>As actual</td></tr><tr><td>Transport (if availed)</td><td>As actual</td></tr><tr><td>NRI seats (15%)</td><td>USD 15,000 for the entire course</td></tr></tbody></table><figcaption class=\"wp-element-caption\">Source: Haryana Govt. Gazette (Extra.), 21 June 2024, Annexure-VI, <a href=\"http://localhost:8092/wp-content/uploads/2026/09/Haryana_Gazette_2024_Nursing_Fee_Structure.pdf\">download PDF</a>.</figcaption></figure>\n<!-- /wp:table -->\n\n<!-- wp:paragraph -->\n<p>Scholarships for SC/BC and other eligible students are available under Government of Haryana and central schemes, subject to their rules. Ask the college office for guidance on applying.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"sr-placeholder\"} -->\n<p class=\"sr-placeholder\">Please confirm which scholarship schemes students of the college commonly use (e.g. Post-Matric Scholarship on the Haryana Saral / NSP portal).</p>\n<!-- /wp:paragraph -->\n','Fee Structure','','inherit','closed','closed','','11-revision-v1','','','2026-09-26 19:18:42','2026-09-26 13:48:42','',11,'http://localhost:8092/?p=30',0,'revision','',0),
(31,0,'2026-09-26 19:18:42','2026-09-26 13:48:42','<!-- wp:paragraph {\"className\":\"has-large-font-size\"} -->\n<p class=\"has-large-font-size\">Our programmes are approved by the national and state regulators for nursing education, and our degrees are awarded by the state health sciences university.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|50\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide\" style=\"margin-top:var(--wp--preset--spacing--50)\">\n<!-- wp:columns -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">National regulator</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Indian Nursing Council, New Delhi</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Approves the B.Sc Nursing, Post Basic B.Sc Nursing, GNM and ANM programmes and their intake.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p><a href=\"https://www.indiannursingcouncil.org\" target=\"_blank\" rel=\"noopener\">indiannursingcouncil.org ↗</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">State council</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Haryana Nurses &amp; Midwives Council</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Recognises the institution in Haryana and registers our graduates as nurses and midwives.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n<!-- wp:columns -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Affiliating university</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Pt. B.D. Sharma University of Health Sciences, Rohtak</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Awards our degrees, conducts entrance tests, counselling and examinations (including GNM finals).</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p><a href=\"https://www.uhsr.ac.in\" target=\"_blank\" rel=\"noopener\">uhsr.ac.in ↗</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">State government</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">DMER, Government of Haryana</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Recognition of the institution; admission counselling and fee norms for nursing colleges.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p><a href=\"https://dmer.haryana.gov.in\" target=\"_blank\" rel=\"noopener\">dmer.haryana.gov.in ↗</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Approval documents</h2>\n<!-- /wp:heading -->\n\n<!-- wp:table -->\n<figure class=\"wp-block-table\"><table><thead><tr><th>Document</th><th>Reference / date</th><th>Download</th></tr></thead><tbody><tr><td>INC approval letter (current session)</td><td>—</td><td>—</td></tr><tr><td>HNRC recognition letter</td><td>—</td><td>—</td></tr><tr><td>UHSR affiliation letter</td><td>—</td><td>—</td></tr><tr><td>Essentiality certificate / Govt. of Haryana NOC</td><td>—</td><td>—</td></tr></tbody></table></figure>\n<!-- /wp:table -->\n\n<!-- wp:paragraph {\"className\":\"sr-placeholder\"} -->\n<p class=\"sr-placeholder\">Please send scanned copies of these letters (PDF) so they can be uploaded and linked here.</p>\n<!-- /wp:paragraph -->\n','Approvals & Affiliations','','inherit','closed','closed','','12-revision-v1','','','2026-09-26 19:18:42','2026-09-26 13:48:42','',12,'http://localhost:8092/?p=31',0,'revision','',0),
(32,0,'2026-09-26 19:18:42','2026-09-26 13:48:42','<!-- wp:paragraph {\"className\":\"has-large-font-size\"} -->\n<p class=\"has-large-font-size\">Shri Ram College has its own <strong>100-bed hospital</strong>, where students gain supervised, hands-on clinical experience, an essential part of becoming a confident professional nurse or technologist.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|50\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide\" style=\"margin-top:var(--wp--preset--spacing--50)\">\n<!-- wp:columns -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Clinical learning</h3>\n<!-- /wp:heading -->\n<!-- wp:list {\"className\":\"sr-icon-list\"} -->\n<ul class=\"wp-block-list sr-icon-list\"><!-- wp:list-item -->\n<li>Bedside nursing care under qualified nursing faculty</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Rotations through medical, surgical, paediatric and maternity wards</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Exposure to emergency, operation theatre and diagnostic services</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Case studies, care plans and clinical presentations</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Community postings</h3>\n<!-- /wp:heading -->\n<!-- wp:list {\"className\":\"sr-icon-list\"} -->\n<ul class=\"wp-block-list sr-icon-list\"><!-- wp:list-item -->\n<li>Community health nursing in the villages around Digrota</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Health surveys, immunisation and awareness drives</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Maternal and child health outreach</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Health camps organised by the college</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Departments &amp; services</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"sr-placeholder\"} -->\n<p class=\"sr-placeholder\">Please share the hospital\'s name, departments/specialities, number of doctors, and OPD timings, along with photographs.</p>\n<!-- /wp:paragraph -->\n','Hospital','','inherit','closed','closed','','13-revision-v1','','','2026-09-26 19:18:42','2026-09-26 13:48:42','',13,'http://localhost:8092/?p=32',0,'revision','',0),
(33,0,'2026-09-26 19:18:42','2026-09-26 13:48:42','<!-- wp:paragraph {\"className\":\"has-large-font-size\"} -->\n<p class=\"has-large-font-size\">Our campus at Digrota is designed for focused study, practical training and a safe residential life.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|50\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide\" style=\"margin-top:var(--wp--preset--spacing--50)\">\n<!-- wp:columns -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Classrooms</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Spacious, fully furnished lecture halls with comfortable seating and advanced teaching aids.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Laboratories</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Labs with models, charts, specimens, microscopes and slides for anatomy, physiology and microbiology, plus nursing skill labs for practical training.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Audio-visual lab</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>OHP, LCD projector, TV, posters, flannel boards, models and other teaching-learning material.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n<!-- wp:columns -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Library</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>A full library with 3,500+ medical and nursing books, 10 journals, Indian and international e-journals, newspapers and magazines.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Auditorium</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>A venue for seminars, workshops, guest lectures and cultural events.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Hostels</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Separate hostels for girls and boys with mess facilities and security.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n<!-- wp:columns -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Canteen</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>A hygienic canteen serving meals and refreshments on campus.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Transport</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>College buses connect the campus with nearby towns and villages.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Wi-Fi campus</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Internet access for learning and research across the campus.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n<!-- wp:columns -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Gym &amp; sports</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>A gym and sports complex for fitness and recreation.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Hospital</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Our own 100-bed hospital for clinical training.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Medical care</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Medical facilities for students on campus.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph {\"className\":\"sr-placeholder\"} -->\n<p class=\"sr-placeholder\">Please share photographs of each facility and the bus routes served.</p>\n<!-- /wp:paragraph -->\n','Campus & Facilities','','inherit','closed','closed','','14-revision-v1','','','2026-09-26 19:18:42','2026-09-26 13:48:42','',14,'http://localhost:8092/?p=33',0,'revision','',0),
