>\n<!-- wp:columns -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:paragraph {\"className\":\"sr-photo-slot\"} -->\n<p class=\"sr-photo-slot\">Lamp-lighting ceremony</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:paragraph {\"className\":\"sr-photo-slot\"} -->\n<p class=\"sr-photo-slot\">Community health camp</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:paragraph {\"className\":\"sr-photo-slot\"} -->\n<p class=\"sr-photo-slot\">Annual function</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n','Gallery','','inherit','closed','closed','','16-revision-v1','','','2026-09-26 19:20:03','2026-09-26 13:50:03','',16,'http://localhost:8092/?p=50',0,'revision','',0),
(51,0,'2026-09-26 19:20:03','2026-09-26 13:50:03','<!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignwide\" style=\"margin-top:0\">\n<!-- wp:columns -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Address</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Shri Ram College of Medical Science &amp; Research<br>VPO Digrota, Nangal Mala Road<br>Tehsil Satnali, Distt. Mahendragarh<br>Haryana – 123024</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p><a href=\"https://www.google.com/maps?q=28.365143,76.040255\" target=\"_blank\" rel=\"noopener\">Open in Google Maps ↗</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Phone &amp; email</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Phone: [sr_contact field=\"phone\"]</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>Email: [sr_contact field=\"email\"]</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-meta\"} -->\n<p class=\"sr-meta\">Office hours: from 9:00 AM</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">How to reach</h3>\n<!-- /wp:heading -->\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>About 50 km by road from Mahendragarh town, via Satnali</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Nearest railway station: Nanwan (NWN)</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Nearest major airport: IGI Airport, New Delhi</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>College buses available on nearby routes</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|50\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignwide\" style=\"margin-top:var(--wp--preset--spacing--50)\">\n<!-- wp:html -->\n<div class=\"sr-map\"><iframe title=\"Map to Shri Ram College, Digrota\" loading=\"lazy\" referrerpolicy=\"no-referrer-when-downgrade\" src=\"https://maps.google.com/maps?q=28.365143,76.040255&amp;z=13&amp;output=embed\"></iframe></div>\n<!-- /wp:html -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|50\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignwide\" style=\"margin-top:var(--wp--preset--spacing--50)\">\n<!-- wp:columns -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Send us an enquiry</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Questions about admissions, courses, fees or hostels? Fill in the form and we will get back to you.</p>\n<!-- /wp:paragraph -->\n<!-- wp:shortcode -->\n[contact-form-7 id=\"5\" title=\"Admission Enquiry\"]\n<!-- /wp:shortcode -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n','Contact Us','','inherit','closed','closed','','17-revision-v1','','','2026-09-26 19:20:03','2026-09-26 13:50:0