(116,0,'2026-09-26 20:18:47','2026-09-26 14:48:47','<!-- wp:group {\"align\":\"full\",\"className\":\"sr-hero\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|70\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n<div class=\"wp-block-group alignfull sr-hero\" style=\"padding-top:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--70)\">\n<!-- wp:columns {\"verticalAlignment\":\"center\",\"align\":\"full\",\"className\":\"sr-split sr-bleed-r sr-hero-cols\"} -->\n<div class=\"wp-block-columns alignfull are-vertically-aligned-center sr-split sr-bleed-r sr-hero-cols\">\n<!-- wp:column {\"className\":\"sr-hero-text\"} -->\n<div class=\"wp-block-column sr-hero-text\">\n<!-- wp:paragraph {\"className\":\"sr-eyebrow\"} -->\n<p class=\"sr-eyebrow\">Digrota · Satnali · Mahendragarh · Haryana</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":1} -->\n<h1 class=\"wp-block-heading\">Shaping skilled, <em>compassionate</em> nurses &amp; healthcare professionals</h1>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-lead\"} -->\n<p class=\"sr-lead\">Nursing and paramedical programmes approved by the Indian Nursing Council and affiliated to Pt. B.D. Sharma University of Health Sciences, Rohtak, with hands-on clinical training at our own 100-bed hospital.</p>\n<!-- /wp:paragraph -->\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/admissions/\">Apply for Admission</a></div>\n<!-- /wp:button --><!-- wp:button {\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" href=\"/courses/\">Explore Courses</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n<!-- wp:group {\"className\":\"sr-badges\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\"}} -->\n<div class=\"wp-block-group sr-badges\">\n<!-- wp:paragraph -->\n<p>✓ INC Approved</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>✓ HNRC Recognised</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>✓ UHSR Rohtak Affiliated</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"sr-hero-art\"} -->\n<div class=\"wp-block-column sr-hero-art\">\n<!-- wp:image {\"id\":85,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"sr-hero-photo\"} -->\n<figure class=\"wp-block-image size-full sr-hero-photo\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/campus-wide.jpg\" alt=\"Shri Ram College campus buildings and lawns, Digrota\" class=\"wp-image-85\"/></figure>\n<!-- /wp:image -->\n<!-- wp:paragraph {\"className\":\"sr-float sr-float--1\"} -->\n<p class=\"sr-float sr-float--1\"><strong>100-bed</strong>attached hospital</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-float sr-float--2\"} -->\n<p class=\"sr-float sr-float--2\"><strong>5</strong>programmes</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"align\":\"wide\",\"className\":\"sr-stats\"} -->\n<div class=\"wp-block-columns alignwide sr-stats\">\n<!-- wp:column {\"className\":\"sr-icon sr-icon--soft ico-bed\"} -->\n<div class=\"wp-block-column sr-icon sr-icon--soft ico-bed\">\n<!-- wp:paragraph {\"className\":\"sr-stat__num\"} -->\n<p class=\"sr-stat__num\">100</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-stat__label\"} -->\n<p class=\"sr-stat__label\">Bed attached hospital</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"sr-icon sr-icon--soft ico-graduation\"} -->\n<div class=\"wp-block-column sr-icon sr-icon--soft ico-graduation\">\n<!-- wp:paragraph {\"className\":\"sr-stat__num\"} -->\n<p class=\"sr-stat__num\">5</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-stat__label\"} -->\n<p class=\"sr-stat__label\">Nursing &amp; paramedical programmes</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"sr-icon sr-icon--soft ico-users\"} -->\n<div class=\"wp-block-column sr-icon sr-icon--soft ico-users\">\n<!-- wp:paragraph {\"className\":\"sr-stat__num\"} -->\n<p class=\"sr-stat__num\">170+</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-stat__label\"} -->\n<p class=\"sr-stat__label\">Approved seats every year</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"sr-icon sr-icon--soft ico-home\"} -->\n<div class=\"wp-block-column sr-icon sr-icon--soft ico-home\">\n<!-- wp:paragraph {\"className\":\"sr-stat__num\"} -->\n<p class=\"sr-stat__num\">2</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-stat__label\"} -->\n<p class=\"sr-stat__label\">Separate hostels for girls &amp; boys</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {\"verticalAlignment\":\"center\",\"align\":\"full\",\"className\":\"sr-split sr-bleed-l\"} -->\n<div class=\"wp-block-columns alignfull are-vertically-aligned-center sr-split sr-bleed-l\">\n<!-- wp:column {\"className\":\"sr-panel sr-panel--teal\"} -->\n<div class=\"wp-block-column sr-panel sr-panel--teal\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Since</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-bignum__n\"} -->\n<p class=\"sr-bignum__n\">2012</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-panel__lead\"} -->\n<p class=\"sr-panel__lead\">A trusted name in nursing education in Mahendragarh district.</p>\n<!-- /wp:paragraph -->\n<!-- wp:list {\"className\":\"sr-icon-list\"} -->\n<ul class=\"wp-block-list sr-icon-list\"><!-- wp:list-item -->\n<li>Approved by the Indian Nursing Council</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Recognised by the Haryana Nurses &amp; Midwives Council</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Affiliated to Pt. B.D. Sharma UHS, Rohtak</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Private, co-educational institution</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"sr-split__text\"} -->\n<div class=\"wp-block-column sr-split__text\">\n<!-- wp:group {\"className\":\"sr-section-head\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-section-head\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">About the college</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Quality nursing education in the heart of rural Haryana</h2>\n<!-- /wp:heading -->\n</div>\n<!-- /wp:group -->\n<!-- wp:paragraph -->\n<p>Shri Ram College of Medical Science &amp; Research at Digrota, Mahendragarh, runs <strong>Shri Ram College of Nursing</strong> and <strong>Shri Ram School of Nursing</strong>, offering degree and diploma programmes in nursing and allied health.</p>\n<!-- /wp:paragraph -->\n<!-- wp:columns {\"className\":\"sr-features\"} -->\n<div class=\"wp-block-columns sr-features\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-feature sr-icon sr-icon--soft ico-hospital\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-feature sr-icon sr-icon--soft ico-hospital\">\n<!-- wp:paragraph -->\n<p><strong>Own 100-bed hospital</strong>Clinical exposure from the early semesters.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"sr-feature sr-icon sr-icon--soft ico-microscope\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-feature sr-icon sr-icon--soft ico-microscope\">\n<!-- wp:paragraph -->\n<p><strong>Modern laboratories</strong>Anatomy, physiology, microbiology &amp; nursing skills.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"sr-feature sr-icon sr-icon--soft ico-book\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-feature sr-icon sr-icon--soft ico-book\">\n<!-- wp:paragraph -->\n<p><strong>Well-stocked library</strong>3,500+ books, journals and e-resources.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-feature sr-icon sr-icon--soft ico-home\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-feature sr-icon sr-icon--soft ico-home\">\n<!-- wp:paragraph -->\n<p><strong>Safe hostels</strong>Separate hostels for girls and boys, with mess.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"sr-feature sr-icon sr-icon--soft ico-bus\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-feature sr-icon sr-icon--soft ico-bus\">\n<!-- wp:paragraph -->\n<p><strong>College transport</strong>Buses on routes around the campus.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"sr-feature sr-icon sr-icon--soft ico-wifi\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-feature sr-icon sr-icon--soft ico-wifi\">\n<!-- wp:paragraph -->\n<p><strong>Wi-Fi campus</strong>Plus a gym, sports complex and canteen.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" href=\"/about/\">More about us</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n\n<!-- wp:group {\"align\":\"full\",\"backgroundColor\":\"light\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1400px\",\"wideSize\":\"1400px\"}} -->\n<div class=\"wp-block-group alignfull has-light-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\">\n<!-- wp:group {\"className\":\"sr-section-head is-centered\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-section-head is-centered\">\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"sr-tag\"} -->\n<p class=\"has-text-align-center sr-tag\">Programmes</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Courses we offer</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Degree and diploma programmes in nursing and allied health sciences.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:columns -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-course sr-icon ico-nurse\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-course sr-icon ico-nurse\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Degree · 4 years</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">B.Sc Nursing</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-meta\"} -->\n<p class=\"sr-meta\">50 seats</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A four-year professional degree that builds a strong foundation in nursing science, anatomy and direct patient care, with extensive hospital practice.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-more\"} -->\n<p class=\"sr-more\"><a href=\"/courses/bsc-nursing/\">View course details</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-course sr-icon ico-graduation\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-course sr-icon ico-graduation\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Degree · 2 years</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Post Basic B.Sc Nursing</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-meta\"} -->\n<p class=\"sr-meta\">40 seats</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A two-year degree for registered GNM nurses who want to upgrade to a B.Sc qualification and take on greater clinical and leadership roles.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-more\"} -->\n<p class=\"sr-more\"><a href=\"/courses/post-basic-bsc-nursing/\">View course details</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-course sr-icon ico-microscope\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-course sr-icon ico-microscope\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Degree · 3 years</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">B.Sc Paramedical Science</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-meta\"} -->\n<p class=\"sr-meta\">50 seats</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A three-year allied-health degree awarded by Pt. B.D. Sharma UHS, Rohtak, preparing technologists for hospital and diagnostic settings.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-more\"} -->\n<p class=\"sr-more\"><a href=\"/courses/bsc-paramedical-science/\">View course details</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n<!-- wp:columns -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-course sr-icon sr-icon--accent ico-stethoscope\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-course sr-icon sr-icon--accent ico-stethoscope\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Diploma · 3 years</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">GNM – General Nursing &amp; Midwifery</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-meta\"} -->\n<p class=\"sr-meta\">Seats as approved</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A diploma programme in general nursing and midwifery, leading to registration as a nurse and midwife with the state council.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-more\"} -->\n<p class=\"sr-more\"><a href=\"/courses/gnm/\">View course details</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-course sr-icon sr-icon--accent ico-heart\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-course sr-icon sr-icon--accent ico-heart\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Diploma · 2 years</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">ANM – Auxiliary Nurse Midwifery</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-meta\"} -->\n<p class=\"sr-meta\">30 seats</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A two-year diploma that trains community health workers in maternal and child health, first aid and primary care.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-more\"} -->\n<p class=\"sr-more\"><a href=\"/courses/anm/\">View course details</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/courses/\">Compare all courses</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"sr-ticker-band\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignfull sr-ticker-band\">\n<!-- wp:html -->\n<div class=\"sr-ticker\" role=\"region\" aria-label=\"Recognition and highlights\"><ul class=\"sr-ticker__track\"><li>INC Approved</li><li>HNRC Recognised</li><li>Affiliated to Pt. B.D. Sharma UHS, Rohtak</li><li>Recognised by Govt. of Haryana</li><li>Own 100-Bed Hospital</li><li>B.Sc Nursing</li><li>Post Basic B.Sc Nursing</li><li>B.Sc Paramedical</li><li>GNM</li><li>ANM</li></ul><ul class=\"sr-ticker__track\" aria-hidden=\"true\"><li>INC Approved</li><li>HNRC Recognised</li><li>Affiliated to Pt. B.D. Sharma UHS, Rohtak</li><li>Recognised by Govt. of Haryana</li><li>Own 100-Bed Hospital</li><li>B.Sc Nursing</li><li>Post Basic B.Sc Nursing</li><li>B.Sc Paramedical</li><li>GNM</li><li>ANM</li></ul></div>\n<!-- /wp:html -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|40\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"680px\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--40)\">\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"sr-tag\"} -->\n<p class=\"has-text-align-center sr-tag\">Life at Shri Ram</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\">A campus built for learning and care</h2>\n<!-- /wp:heading -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"align\":\"full\",\"className\":\"sr-mosaic sr-mosaic--photos\"} -->\n<div class=\"wp-block-columns alignfull sr-mosaic sr-mosaic--photos\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"id\":111,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/students-batch.jpg\" alt=\"A batch of nursing students on the college lawn\" class=\"wp-image-111\"/><figcaption class=\"wp-element-caption\">Photo: DS KNOWLEDGE via Google Maps</figcaption></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"id\":96,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/skill-practice.jpg\" alt=\"Students practising bed making in the nursing skill lab\" class=\"wp-image-96\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"id\":99,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/library-hall.jpg\" alt=\"Spacious library hall with reading tables\" class=\"wp-image-99\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"id\":91,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/hospital-ward.jpg\" alt=\"Hospital ward with beds and screens\" class=\"wp-image-91\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"id\":100,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/classroom-students.jpg\" alt=\"Nursing students attending a lecture\" class=\"wp-image-100\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"sr-dark sr-pillars\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n<div class=\"wp-block-group alignfull sr-dark sr-pillars\" style=\"padding-top:var(--wp--preset--spacing--60)\">\n<!-- wp:group {\"layout\":{\"type\":\"constrained\",\"contentSize\":\"680px\"}} -->\n<div class=\"wp-block-group\">\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"sr-tag\"} -->\n<p class=\"has-text-align-center sr-tag\">Our pillars</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Care. Compassion. Competence.</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Three values that guide how we teach and how our students serve.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:columns {\"align\":\"full\",\"className\":\"sr-tiles\"} -->\n<div class=\"wp-block-columns alignfull sr-tiles\">\n<!-- wp:column {\"className\":\"sr-tile\"} -->\n<div class=\"wp-block-column sr-tile\">\n<!-- wp:group {\"className\":\"sr-pillar sr-icon sr-icon--accent ico-hands\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-pillar sr-icon sr-icon--accent ico-hands\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Care</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Patient-centred nursing is at the heart of everything we teach, from the first classroom lesson to the hospital ward.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"sr-tile\"} -->\n<div class=\"wp-block-column sr-tile\">\n<!-- wp:group {\"className\":\"sr-pillar sr-icon sr-icon--accent ico-heart\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-pillar sr-icon sr-icon--accent ico-heart\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Compassion</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>We shape professionals who treat every patient with dignity, empathy and respect, whatever their background.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"sr-tile\"} -->\n<div class=\"wp-block-column sr-tile\">\n<!-- wp:group {\"className\":\"sr-pillar sr-icon sr-icon--accent ico-award\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-pillar sr-icon sr-icon--accent ico-award\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Competence</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Strong science, supervised clinical practice and professional ethics prepare graduates for real-world healthcare.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"verticalAlignment\":\"center\",\"align\":\"full\",\"className\":\"sr-split sr-bleed-l sr-split--light\"} -->\n<div class=\"wp-block-columns alignfull are-vertically-aligned-center sr-split sr-bleed-l sr-split--light\">\n<!-- wp:column {\"className\":\"sr-panel sr-panel--navy\"} -->\n<div class=\"wp-block-column sr-panel sr-panel--navy\">\n<!-- wp:image {\"id\":87,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"sr-panel-photo\"} -->\n<figure class=\"wp-block-image size-full sr-panel-photo\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/hospital-building.jpg\" alt=\"Shri Ram Hospital building on the college campus\" class=\"wp-image-87\"/></figure>\n<!-- /wp:image -->\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Clinical training</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-bignum__n\"} -->\n<p class=\"sr-bignum__n\">100</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">bed hospital on our own campus</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Students learn at the bedside under supervision, rotating through wards and services, alongside community health postings in the surrounding villages.</p>\n<!-- /wp:paragraph -->\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/hospital/\">About the hospital</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"sr-split__text\"} -->\n<div class=\"wp-block-column sr-split__text\">\n<!-- wp:group {\"className\":\"sr-section-head\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-section-head\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Campus life</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Everything you need on one campus</h2>\n<!-- /wp:heading -->\n</div>\n<!-- /wp:group -->\n<!-- wp:columns -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-icon--sm sr-icon sr-icon--soft ico-monitor\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-icon--sm sr-icon sr-icon--soft ico-monitor\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Classrooms</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Spacious halls with audio-visual aids.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"sr-card sr-icon--sm sr-icon sr-icon--soft ico-stage\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-icon--sm sr-icon sr-icon--soft ico-stage\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Auditorium</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Seminars, workshops and events.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-icon--sm sr-icon sr-icon--soft ico-flask\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-icon--sm sr-icon sr-icon--soft ico-flask\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Skill labs</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Hands-on practice before the ward.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"sr-card sr-icon--sm sr-icon sr-icon--soft ico-utensils\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-icon--sm sr-icon sr-icon--soft ico-utensils\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Canteen &amp; gym</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Hygienic food, fitness and sports.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n<!-- wp:paragraph {\"className\":\"sr-more\"} -->\n<p class=\"sr-more\"><a href=\"/campus-facilities/\">Explore all facilities</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"960px\",\"wideSize\":\"960px\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\">\n<!-- wp:group {\"className\":\"sr-section-head is-centered\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-section-head is-centered\">\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"sr-tag\"} -->\n<p class=\"has-text-align-center sr-tag\">Admissions</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Your path to a nursing career</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Admissions follow the rules of DMER Haryana and Pt. B.D. Sharma UHS, Rohtak.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:columns {\"className\":\"sr-steps\"} -->\n<div class=\"wp-block-columns sr-steps\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-step\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-step\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Check eligibility</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>10+2 with the required subjects and marks; minimum age 17 by 31 December.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-step\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-step\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Apply / appear</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>B.Sc courses: UHSR entrance test &amp; counselling. ANM/GNM: merit-based.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-step\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-step\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Choose Shri Ram</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Select Shri Ram College of Nursing, Digrota, in counselling, or contact us.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-step\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-step\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Report &amp; enrol</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Bring original documents, pay the fee and begin your journey.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/admissions/\">Admission details</a></div>\n<!-- /wp:button --><!-- wp:button {\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" href=\"/fee-structure/\">Fee structure</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"verticalAlignment\":\"center\",\"align\":\"full\",\"className\":\"sr-split sr-bleed-r\"} -->\n<div class=\"wp-block-columns alignfull are-vertically-aligned-center sr-split sr-bleed-r\">\n<!-- wp:column {\"className\":\"sr-split__text\"} -->\n<div class=\"wp-block-column sr-split__text\">\n<!-- wp:group {\"className\":\"sr-section-head\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-section-head\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Latest</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Notices &amp; announcements</h2>\n<!-- /wp:heading -->\n</div>\n<!-- /wp:group -->\n<!-- wp:query {\"queryId\":2,\"query\":{\"perPage\":3,\"postType\":\"post\",\"order\":\"desc\",\"orderBy\":\"date\",\"inherit\":false},\"className\":\"sr-notices\"} -->\n<div class=\"wp-block-query sr-notices\">\n<!-- wp:post-template -->\n<!-- wp:post-date {\"fontSize\":\"small\"} /-->\n<!-- wp:post-title {\"isLink\":true,\"level\":3} /-->\n<!-- /wp:post-template -->\n<!-- wp:query-no-results -->\n<!-- wp:paragraph -->\n<p>New notices will appear here.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:query-no-results -->\n</div>\n<!-- /wp:query -->\n<!-- wp:paragraph {\"className\":\"sr-more\"} -->\n<p class=\"sr-more\"><a href=\"/notices/\">All notices</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"sr-panel sr-panel--cta sr-icon sr-icon--accent ico-lamp\"} -->\n<div class=\"wp-block-column sr-panel sr-panel--cta sr-icon sr-icon--accent ico-lamp\">\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Begin your career in healthcare</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Talk to our admissions team about courses, eligibility, fees and hostel availability.</p>\n<!-- /wp:paragraph -->\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/contact/\">Contact Admissions</a></div>\n<!-- /wp:button --><!-- wp:button {\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" href=\"/admissions/\">Admission Process</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n','Home','','inherit','closed','closed','','7-revision-v1','','','2026-09-26 20:18:47','2026-09-26 14:48:47','',7,'http://localhost:8092/?p=116',0,'revision','',0),
(117,0,'2026-09-26 20:18:47','2026-09-26 14:48:47','<!-- wp:paragraph {\"className\":\"has-large-font-size\"} -->\n<p class=\"has-large-font-size\">Shri Ram College of Medical Science &amp; Research, Digrota (Mahendragarh), is a private, co-educational institution for nursing and allied health education. Through <strong>Shri Ram College of Nursing</strong> (degree programmes) and <strong>Shri Ram School of Nursing</strong> (diploma programmes), it has served students of Mahendragarh and the surrounding districts since 2012.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The college is approved by the Indian Nursing Council (INC), New Delhi, and the Haryana Nurses &amp; Midwives Council, and is affiliated to Pt. B.D. Sharma University of Health Sciences, Rohtak. The campus has spacious, fully furnished classrooms, well-established laboratories, a comprehensive library and an auditorium. Students also train at our own 100-bed hospital, which gives them the clinical exposure a good nurse needs.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The institution is run by <strong>Shri Ram Krishan Param Hans Shiksha Parishad</strong> and is part of the <strong>Shri Ram Group of Institutions (SRGI), Haryana</strong>. On the same campus, the group also runs <strong>Shri Ram Ayurvedic Medical College &amp; Hospital</strong>, offering the BAMS programme, approved by CCIM, New Delhi (Ministry of AYUSH) and affiliated to Shri Krishna AYUSH University, Kurukshetra.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"sr-placeholder\"} -->\n<p class=\"sr-placeholder\">Please confirm the year each institution was established (online sources say 2012 for the group and 2019 for the College of Nursing) and the name of the managing trust or society.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns {\"verticalAlignment\":\"center\",\"align\":\"full\",\"className\":\"sr-split sr-bleed-r\"} -->\n<div class=\"wp-block-columns alignfull are-vertically-aligned-center sr-split sr-bleed-r\">\n<!-- wp:column {\"className\":\"sr-split__text\"} -->\n<div class=\"wp-block-column sr-split__text\">\n<!-- wp:group {\"className\":\"sr-vision sr-icon ico-eye\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-vision sr-icon ico-eye\">\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Our Vision</h2>\n<!-- /wp:heading -->\n</div>\n<!-- /wp:group -->\n<!-- wp:paragraph {\"className\":\"has-large-font-size\"} -->\n<p class=\"has-large-font-size\">To be a leading centre of nursing and paramedical education in rural Haryana, producing competent, ethical and compassionate healthcare professionals who serve their communities.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"sr-panel sr-panel--teal sr-icon sr-icon--accent ico-target\"} -->\n<div class=\"wp-block-column sr-panel sr-panel--teal sr-icon sr-icon--accent ico-target\">\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Our Mission</h2>\n<!-- /wp:heading -->\n<!-- wp:list {\"className\":\"sr-icon-list\"} -->\n<ul class=\"wp-block-list sr-icon-list\"><!-- wp:list-item -->\n<li>Deliver INC and university-standard education with strong clinical training</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Make quality healthcare education accessible to rural students, especially young women</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Instil empathy, discipline and professional ethics</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Serve the community through health camps and outreach</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n\n<!-- wp:paragraph {\"className\":\"sr-placeholder\"} -->\n<p class=\"sr-placeholder\">The Vision and Mission above are drafts written for the website. Please review or replace them with the college\'s official statements.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"align\":\"full\",\"backgroundColor\":\"light\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"960px\",\"wideSize\":\"960px\"}} -->\n<div class=\"wp-block-group alignfull has-light-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\">\n<!-- wp:group {\"className\":\"sr-section-head is-centered\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-section-head is-centered\">\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"sr-tag\"} -->\n<p class=\"has-text-align-center sr-tag\">Key facts</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\">At a glance</h2>\n<!-- /wp:heading -->\n</div>\n<!-- /wp:group -->\n<!-- wp:table -->\n<figure class=\"wp-block-table\"><table><tbody><tr><td>Location</td><td>VPO Digrota, Nangal Mala Road, Tehsil Satnali, Distt. Mahendragarh, Haryana – 123024</td></tr><tr><td>Managing society</td><td>Shri Ram Krishan Param Hans Shiksha Parishad (Shri Ram Group of Institutions, Haryana)</td></tr><tr><td>Type</td><td>Private (self-financed), co-educational</td></tr><tr><td>Approvals</td><td>Indian Nursing Council (INC), New Delhi; Haryana Nurses &amp; Midwives Council (HNRC)</td></tr><tr><td>Affiliation</td><td>Pt. B.D. Sharma University of Health Sciences, Rohtak</td></tr><tr><td>Programmes</td><td>B.Sc Nursing, Post Basic B.Sc Nursing, B.Sc Paramedical Science, GNM, ANM</td></tr><tr><td>Hospital</td><td>Own 100-bed hospital for clinical training</td></tr><tr><td>Residential</td><td>Separate hostels for girls and boys</td></tr></tbody></table></figure>\n<!-- /wp:table -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|50\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignwide\" style=\"margin-top:var(--wp--preset--spacing--50)\">\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Leadership</h2>\n<!-- /wp:heading -->\n<!-- wp:columns -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-icon sr-icon--soft ico-idcard\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-icon sr-icon--soft ico-idcard\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Chairman</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Sh. Sukesh Diwan</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-meta\"} -->\n<p class=\"sr-meta\">Chairman, Shri Ram Group of Institutions</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-icon sr-icon--soft ico-idcard\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-icon sr-icon--soft ico-idcard\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">CEO</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Sh. Manish Diwan</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-meta\"} -->\n<p class=\"sr-meta\">Chief Executive Officer, Shri Ram Group of Institutions</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-icon sr-icon--soft ico-idcard\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-icon sr-icon--soft ico-idcard\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Director</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Sh. Hawa Singh</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-meta\"} -->\n<p class=\"sr-meta\">Director</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-icon sr-icon--soft ico-idcard\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-icon sr-icon--soft ico-idcard\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Principal</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Name to be added</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-placeholder\"} -->\n<p class=\"sr-placeholder\">Principal\'s name, photo and message.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n<!-- wp:paragraph {\"className\":\"sr-placeholder\"} -->\n<p class=\"sr-placeholder\">Leadership names are taken from the college\'s 2018–19 admission notice posted on its Google listing. Please confirm they are current and send photos and messages.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n','About the College','','inherit','closed','closed','','8-revision-v1','','','2026-09-26 20:18:47','2026-09-26 14:48:47','',8,'http://localhost:8092/?p=117',0,'revision','',0),
(118,0,'2026-09-26 20:18:47','2026-09-26 14:48:47','<!-- wp:paragraph {\"className\":\"has-large-font-size\"} -->\n<p class=\"has-large-font-size\">We offer degree and diploma programmes in nursing and allied health sciences. All nursing programmes are approved by the Indian Nursing Council and the Haryana Nurses &amp; Midwives Council. Degrees are awarded by Pt. B.D. Sharma University of Health Sciences, Rohtak.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|50\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignwide\" style=\"margin-top:var(--wp--preset--spacing--50)\">\n<!-- wp:table -->\n<figure class=\"wp-block-table\"><table><thead><tr><th>Programme</th><th>Level</th><th>Duration</th><th>Seats</th><th>Minimum qualification</th></tr></thead><tbody><tr><td><a href=\"/courses/bsc-nursing/\">B.Sc Nursing</a></td><td>UG Degree</td><td>4 years</td><td>50</td><td>10+2 with PCB &amp; English (50%)</td></tr><tr><td><a href=\"/courses/post-basic-bsc-nursing/\">Post Basic B.Sc Nursing</a></td><td>UG Degree</td><td>2 years</td><td>40</td><td>10+2 + GNM, registered nurse &amp; midwife</td></tr><tr><td><a href=\"/courses/bsc-paramedical-science/\">B.Sc Paramedical Science</a></td><td>UG Degree</td><td>3 years</td><td>50</td><td>10+2 with Science</td></tr><tr><td><a href=\"/courses/gnm/\">GNM</a></td><td>Diploma</td><td>3 years</td><td>As approved</td><td>10+2 (any stream)</td></tr><tr><td><a href=\"/courses/anm/\">ANM</a></td><td>Diploma</td><td>2 years</td><td>30</td><td>10+2 (any stream)</td></tr><tr><td>BAMS (Ayurveda) *</td><td>UG Degree</td><td>5½ years</td><td>—</td><td>10+2 with PCB + NEET</td></tr></tbody></table><figcaption class=\"wp-element-caption\">* BAMS is offered by Shri Ram Ayurvedic Medical College &amp; Hospital on the same campus (CCIM / Ministry of AYUSH; Shri Krishna AYUSH University, Kurukshetra). Seat numbers are the approved intake published by the regulators and may change each session.</figcaption></figure>\n<!-- /wp:table -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"backgroundColor\":\"light\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1400px\",\"wideSize\":\"1400px\"}} -->\n<div class=\"wp-block-group alignfull has-light-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\">\n<!-- wp:columns -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-course sr-icon ico-nurse\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-course sr-icon ico-nurse\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Degree · 4 years</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">B.Sc Nursing</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-meta\"} -->\n<p class=\"sr-meta\">50 seats</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A four-year professional degree that builds a strong foundation in nursing science, anatomy and direct patient care, with extensive hospital practice.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-more\"} -->\n<p class=\"sr-more\"><a href=\"/courses/bsc-nursing/\">View course details</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-course sr-icon ico-graduation\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-course sr-icon ico-graduation\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Degree · 2 years</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Post Basic B.Sc Nursing</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-meta\"} -->\n<p class=\"sr-meta\">40 seats</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A two-year degree for registered GNM nurses who want to upgrade to a B.Sc qualification and take on greater clinical and leadership roles.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-more\"} -->\n<p class=\"sr-more\"><a href=\"/courses/post-basic-bsc-nursing/\">View course details</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-course sr-icon ico-microscope\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-course sr-icon ico-microscope\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Degree · 3 years</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">B.Sc Paramedical Science</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-meta\"} -->\n<p class=\"sr-meta\">50 seats</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A three-year allied-health degree awarded by Pt. B.D. Sharma UHS, Rohtak, preparing technologists for hospital and diagnostic settings.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-more\"} -->\n<p class=\"sr-more\"><a href=\"/courses/bsc-paramedical-science/\">View course details</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n<!-- wp:columns -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-course sr-icon sr-icon--accent ico-stethoscope\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-course sr-icon sr-icon--accent ico-stethoscope\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Diploma · 3 years</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">GNM – General Nursing &amp; Midwifery</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-meta\"} -->\n<p class=\"sr-meta\">Seats as approved</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A diploma programme in general nursing and midwifery, leading to registration as a nurse and midwife with the state council.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-more\"} -->\n<p class=\"sr-more\"><a href=\"/courses/gnm/\">View course details</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-course sr-icon sr-icon--accent ico-heart\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-course sr-icon sr-icon--accent ico-heart\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Diploma · 2 years</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">ANM – Auxiliary Nurse Midwifery</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-meta\"} -->\n<p class=\"sr-meta\">30 seats</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A two-year diploma that trains community health workers in maternal and child health, first aid and primary care.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-more\"} -->\n<p class=\"sr-more\"><a href=\"/courses/anm/\">View course details</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"sr-dark sr-cta-band\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"680px\"}} -->\n<div class=\"wp-block-group alignfull sr-dark sr-cta-band\" style=\"padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\">\n<!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Not sure which course fits you?</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Our admissions team can guide you on eligibility, seats and career paths.</p>\n<!-- /wp:paragraph -->\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/contact/\">Talk to admissions</a></div>\n<!-- /wp:button --><!-- wp:button {\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" href=\"/admissions/\">Admission process</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n</div>\n<!-- /wp:group -->\n','Courses','','inherit','closed','closed','','9-revision-v1','','','2026-09-26 20:18:47','2026-09-26 14:48:47','',9,'http://localhost:8092/?p=118',0,'revision','',0),
(119,0,'2026-09-26 20:18:47','2026-09-26 14:48:47','<!-- wp:paragraph {\"className\":\"has-large-font-size\"} -->\n<p class=\"has-large-font-size\">Shri Ram College has its own <strong>100-bed hospital</strong>, where students gain supervised, hands-on clinical experience, an essential part of becoming a confident professional nurse or technologist.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns {\"verticalAlignment\":\"center\",\"align\":\"full\",\"className\":\"sr-split sr-bleed-l\"} -->\n<div class=\"wp-block-columns alignfull are-vertically-aligned-center sr-split sr-bleed-l\">\n<!-- wp:column {\"className\":\"sr-panel sr-panel--navy\"} -->\n<div class=\"wp-block-column sr-panel sr-panel--navy\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Attached hospital</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-bignum__n\"} -->\n<p class=\"sr-bignum__n\">100</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-panel__lead\"} -->\n<p class=\"sr-panel__lead\">beds for supervised clinical practice on our own campus.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"sr-split__text\"} -->\n<div class=\"wp-block-column sr-split__text\">\n<!-- wp:group {\"className\":\"sr-section-head\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-section-head\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">On the wards</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Learning where care happens</h2>\n<!-- /wp:heading -->\n</div>\n<!-- /wp:group -->\n<!-- wp:paragraph -->\n<p>From the early semesters, students move from skill labs to real patients under the guidance of nursing faculty and hospital staff, building confidence one posting at a time.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n\n<!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|50\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignwide\" style=\"margin-top:var(--wp--preset--spacing--50)\">\n<!-- wp:columns -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-icon ico-stethoscope\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-icon ico-stethoscope\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Clinical learning</h3>\n<!-- /wp:heading -->\n<!-- wp:list {\"className\":\"sr-icon-list\"} -->\n<ul class=\"wp-block-list sr-icon-list\"><!-- wp:list-item -->\n<li>Bedside nursing care under qualified nursing faculty</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Rotations through medical, surgical, paediatric and maternity wards</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Exposure to emergency, operation theatre and diagnostic services</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Case studies, care plans and clinical presentations</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-icon sr-icon--accent ico-users\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-icon sr-icon--accent ico-users\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Community postings</h3>\n<!-- /wp:heading -->\n<!-- wp:list {\"className\":\"sr-icon-list\"} -->\n<ul class=\"wp-block-list sr-icon-list\"><!-- wp:list-item -->\n<li>Community health nursing in the villages around Digrota</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Health surveys, immunisation and awareness drives</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Maternal and child health outreach</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Health camps organised by the college</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"align\":\"full\",\"className\":\"sr-mosaic sr-mosaic--photos\"} -->\n<div class=\"wp-block-columns alignfull sr-mosaic sr-mosaic--photos\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"id\":91,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/hospital-ward.jpg\" alt=\"Hospital ward with beds and screens\" class=\"wp-image-91\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"id\":93,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/emergency.jpg\" alt=\"Emergency department entrance in the college hospital\" class=\"wp-image-93\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"id\":94,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/maternity-room.jpg\" alt=\"Examination room with delivery table\" class=\"wp-image-94\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n<!-- wp:columns {\"align\":\"full\",\"className\":\"sr-mosaic sr-mosaic--photos\"} -->\n<div class=\"wp-block-columns alignfull sr-mosaic sr-mosaic--photos\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"id\":107,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/skill-lab-bed.jpg\" alt=\"Patient simulator on a bed in the skill lab\" class=\"wp-image-107\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"id\":92,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/hospital-ward-2.jpg\" alt=\"Demonstration ward with hospital beds\" class=\"wp-image-92\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"id\":97,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/ward-visit.jpg\" alt=\"Faculty and visitors during a ward inspection\" class=\"wp-image-97\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Departments &amp; services</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"sr-placeholder\"} -->\n<p class=\"sr-placeholder\">Please share the hospital\'s name, departments/specialities, number of doctors, and OPD timings, along with photographs.</p>\n<!-- /wp:paragraph -->\n','Hospital','','inherit','closed','closed','','13-revision-v1','','','2026-09-26 20:18:47','2026-09-26 14:48:47','',13,'http://localhost:8092/?p=119',0,'revision','',0),
(120,0,'2026-09-26 20:18:47','2026-09-26 14:48:47','<!-- wp:paragraph {\"className\":\"has-large-font-size\"} -->\n<p class=\"has-large-font-size\">Our campus at Digrota is designed for focused study, practical training and a safe residential life.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"sr-placeholder\"} -->\n<p class=\"sr-placeholder\">Please share photographs of the hostels, canteen, buses, auditorium and sports facilities, and the bus routes served.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"align\":\"full\",\"backgroundColor\":\"light\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1400px\",\"wideSize\":\"1400px\"}} -->\n<div class=\"wp-block-group alignfull has-light-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\">\n<!-- wp:columns -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-card--photo\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-card--photo\">\n<!-- wp:image {\"id\":101,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"sr-card__img\"} -->\n<figure class=\"wp-block-image size-full sr-card__img\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/classroom.jpg\" alt=\"Lecture hall with students\" class=\"wp-image-101\"/></figure>\n<!-- /wp:image -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Classrooms</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Spacious, fully furnished lecture halls with comfortable seating and advanced teaching aids.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-card--photo\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-card--photo\">\n<!-- wp:image {\"id\":104,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"sr-card__img\"} -->\n<figure class=\"wp-block-image size-full sr-card__img\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/anatomy-models.jpg\" alt=\"Anatomy models and specimens in the lab\" class=\"wp-image-104\"/></figure>\n<!-- /wp:image -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Laboratories</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Labs with models, charts, specimens, microscopes and slides for anatomy, physiology and microbiology, plus nursing skill labs for practical training.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-card--photo\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-card--photo\">\n<!-- wp:image {\"id\":108,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"sr-card__img\"} -->\n<figure class=\"wp-block-image size-full sr-card__img\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/lab-hall.jpg\" alt=\"Pre-clinical lab hall with charts and models\" class=\"wp-image-108\"/></figure>\n<!-- /wp:image -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Audio-visual lab</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>OHP, LCD projector, TV, posters, flannel boards, models and other teaching-learning material.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-card--photo\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-card--photo\">\n<!-- wp:image {\"id\":98,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"sr-card__img\"} -->\n<figure class=\"wp-block-image size-full sr-card__img\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/library.jpg\" alt=\"College library reading hall\" class=\"wp-image-98\"/></figure>\n<!-- /wp:image -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Library</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>A full library with 3,500+ medical and nursing books, 10 journals, Indian and international e-journals, newspapers and magazines.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n<!-- wp:columns -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-icon ico-users\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-icon ico-users\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Auditorium</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>A venue for seminars, workshops, guest lectures and cultural events.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-icon sr-icon--accent ico-home\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-icon sr-icon--accent ico-home\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Hostels</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Separate hostels for girls and boys with mess facilities and security.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-icon ico-utensils\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-icon ico-utensils\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Canteen</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>A hygienic canteen serving meals and refreshments on campus.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-icon sr-icon--accent ico-bus\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-icon sr-icon--accent ico-bus\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Transport</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>College buses connect the campus with nearby towns and villages.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n<!-- wp:columns -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-icon ico-wifi\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-icon ico-wifi\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Wi-Fi campus</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Internet access for learning and research across the campus.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-icon sr-icon--accent ico-dumbbell\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-icon sr-icon--accent ico-dumbbell\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Gym &amp; sports</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>A gym and sports complex for fitness and recreation.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-card--photo\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-card--photo\">\n<!-- wp:image {\"id\":91,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"sr-card__img\"} -->\n<figure class=\"wp-block-image size-full sr-card__img\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/hospital-ward.jpg\" alt=\"Hospital ward with beds and screens\" class=\"wp-image-91\"/></figure>\n<!-- /wp:image -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Hospital</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Our own 100-bed hospital for clinical training.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-card--photo\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-card--photo\">\n<!-- wp:image {\"id\":93,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"sr-card__img\"} -->\n<figure class=\"wp-block-image size-full sr-card__img\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/emergency.jpg\" alt=\"Emergency department entrance in the college hospital\" class=\"wp-image-93\"/></figure>\n<!-- /wp:image -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Medical care</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Medical facilities for students on campus.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"sr-dark sr-cta-band\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"680px\"}} -->\n<div class=\"wp-block-group alignfull sr-dark sr-cta-band\" style=\"padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\">\n<!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\">See the campus for yourself</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Visitors and parents are welcome. Contact the college office to plan a visit.</p>\n<!-- /wp:paragraph -->\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/contact/\">Plan a visit</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n</div>\n<!-- /wp:group -->\n','Campus & Facilities','','inherit','closed','closed','','14-revision-v1','','','2026-09-26 20:18:47','2026-09-26 14:48:47','',14,'http://localhost:8092/?p=120',0,'revision','',0),
(121,0,'2026-09-26 20:18:47','2026-09-26 14:48:47','<!-- wp:paragraph {\"className\":\"has-large-font-size\"} -->\n<p class=\"has-large-font-size\">A glimpse of life at Shri Ram College: the campus, our hospital and labs, and our students.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Campus</h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"align\":\"full\",\"className\":\"sr-mosaic sr-mosaic--photos\"} -->\n<div class=\"wp-block-columns alignfull sr-mosaic sr-mosaic--photos\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"id\":85,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/campus-wide.jpg\" alt=\"Shri Ram College campus buildings and lawns, Digrota\" class=\"wp-image-85\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"id\":88,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/main-gate.jpg\" alt=\"Main gate of Shri Ram Medical College & Hospital\" class=\"wp-image-88\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"id\":86,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/campus-building.jpg\" alt=\"Main academic building of Shri Ram College, Digrota\" class=\"wp-image-86\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n<!-- wp:columns {\"align\":\"full\",\"className\":\"sr-mosaic sr-mosaic--photos\"} -->\n<div class=\"wp-block-columns alignfull sr-mosaic sr-mosaic--photos\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"id\":87,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/hospital-building.jpg\" alt=\"Shri Ram Hospital building on the college campus\" class=\"wp-image-87\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"id\":90,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/campus-evening.jpg\" alt=\"College building at dusk\" class=\"wp-image-90\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"id\":89,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/main-gate-2018.jpg\" alt=\"Entrance gate of Shri Ram Medical College & Hospital\" class=\"wp-image-89\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Hospital &amp; laboratories</h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"align\":\"full\",\"className\":\"sr-mosaic sr-mosaic--photos\"} -->\n<div class=\"wp-block-columns alignfull sr-mosaic sr-mosaic--photos\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"id\":91,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/hospital-ward.jpg\" alt=\"Hospital ward with beds and screens\" class=\"wp-image-91\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"id\":93,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8092/wp-content/uplo