full\",\"className\":\"sr-mosaic sr-mosaic--photos\"} -->\n<div class=\"wp-block-columns alignfull sr-mosaic sr-mosaic--photos\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"id\":98,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/library.jpg\" alt=\"College library reading hall\" class=\"wp-image-98\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"id\":103,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/herbal-lab.jpg\" alt=\"Visitors in the laboratory with herbal specimen charts\" class=\"wp-image-103\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"id\":106,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/anatomy-mannequin.jpg\" alt=\"Human anatomy mannequin\" class=\"wp-image-106\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Student life</h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"align\":\"full\",\"className\":\"sr-mosaic sr-mosaic--photos\"} -->\n<div class=\"wp-block-columns alignfull sr-mosaic sr-mosaic--photos\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"id\":110,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/students-group.jpg\" alt=\"Nursing students in uniform, group photo\" class=\"wp-image-110\"/><figcaption class=\"wp-element-caption\">Photo: AMRIT SINGH via Google Maps</figcaption></figur