(123,0,'2026-09-26 20:18:47','2026-09-26 14:48:47','<!-- wp:paragraph -->\n<p>Information disclosed in line with the requirements of the Indian Nursing Council and the affiliating university.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:table -->\n<figure class=\"wp-block-table\"><table><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td>Name of institution</td><td>Shri Ram College of Nursing / Shri Ram School of Nursing (Shri Ram College of Medical Science &amp; Research)</td></tr><tr><td>Address</td><td>VPO Digrota, Nangal Mala Road, Tehsil Satnali, Distt. Mahendragarh, Haryana – 123024</td></tr><tr><td>Managing society</td><td>Shri Ram Krishan Param Hans Shiksha Parishad</td></tr><tr><td>Year of establishment</td><td>—</td></tr><tr><td>Approvals</td><td>Indian Nursing Council; Haryana Nurses &amp; Midwives Council</td></tr><tr><td>Affiliating university</td><td>Pt. B.D. Sharma University of Health Sciences, Rohtak</td></tr><tr><td>Courses &amp; intake</td><td>B.Sc Nursing (50), Post Basic B.Sc Nursing (40), B.Sc Paramedical Science (50), ANM (30), GNM (—)</td></tr><tr><td>Parent hospital</td><td>Own 100-bed hospital</td></tr><tr><td>Principal</td><td>—</td></tr><tr><td>Fee structure</td><td><a href=\"/fee-structure/\">See Fee Structure</a></td></tr><tr><td>Anti-ragging committee</td><td>—</td></tr><tr><td>Grievance redressal / Internal complaints committee</td><td>—</td></tr></tbody></table></figure>\n<!-- /wp:table -->\n\n<!-- wp:paragraph {\"className\":\"sr-placeholder\"} -->\n<p class=\"sr-placeholder\">Please fill in the blank rows and send committee member lists, so this page meets the regulator\'s disclosure requirements.</p>\n<!-- /wp:paragraph -->\n','Mandatory Disclosure','','inherit','closed','closed','','18-revision-v1','','','2026-09-26 20:18:47','2026-09-26 14:48:47','',18,'http://localhost:8092/?p=123',0,'revision','',0),
(124,0,'2026-09-26 20:46:28','2026-09-26 15:16:28','<!-- wp:cover {\"url\":\"http://localhost:8092/wp-content/uploads/2026/09/campus-wide.jpg\",\"id\":85,\"dimRatio\":90,\"overlayColor\":\"dark\",\"isDark\":true,\"align\":\"full\",\"className\":\"sr-hero\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n<div class=\"wp-block-cover alignfull is-dark sr-hero\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-dark-background-color has-background-dim-90 has-background-dim\"></span><img class=\"wp-block-cover__image-background wp-image-85\" alt=\"\" src=\"http://localhost:8092/wp-content/uploads/2026/09/campus-wide.jpg\" data-object-fit=\"cover\"/><div class=\"wp-block-cover__inner-container\">\n<!-- wp:columns {\"verticalAlignment\":\"center\",\"align\":\"full\",\"className\":\"sr-split sr-bleed-r sr-hero-cols\"} -->\n<div class=\"wp-block-columns alignfull are-vertically-aligned-center sr-split sr-bleed-r sr-hero-cols\">\n<!-- wp:column {\"className\":\"sr-hero-text\"} -->\n<div class=\"wp-block-column sr-hero-text\">\n<!-- wp:paragraph {\"className\":\"sr-eyebrow\"} -->\n<p class=\"sr-eyebrow\">Digrota · Satnali · Mahendragarh · Haryana</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":1} -->\n<h1 class=\"wp-block-heading\">Shaping skilled, <em>compassionate</em> nurses &amp; healthcare professionals</h1>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-lead\"} -->\n<p class=\"sr-lead\">Nursing and paramedical programmes approved by the Indian Nursing Council and affiliated to Pt. B.D. Sharma University of Health Sciences, Rohtak, with hands-on clinical training at our own 100-bed hospital.</p>\n<!-- /wp:paragraph -->\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/admissions/\">Apply for Admission</a></div>\n<!-- /wp:button --><!-- wp:button {\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" href=\"/courses/\">Explore Courses</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n<!-- wp:group {\"className\":\"sr-badges\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\"}} -->\n<div class=\"wp-block-group sr-badges\">\n<!-- wp:paragraph -->\n<p>✓ INC Approved</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>✓ HNRC Recognised</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>✓ UHSR Rohtak Affiliated</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"sr-hero-art\"} -->\n<div class=\"wp-block-column sr-hero-art\">\n<!-- wp:image {\"sizeSlug\":\"full\",\"className\":\"sr-hero-img\"} -->\n<figure class=\"wp-block-image size-full sr-hero-img\"><img src=\"http://localhost:8092/wp-content/themes/shriram-college/assets/images/hero-illustration.svg\" alt=\"Illustration of the college hospital with a heartbeat line\"/></figure>\n<!-- /wp:image -->\n<!-- wp:paragraph {\"className\":\"sr-float sr-float--1\"} -->\n<p class=\"sr-float sr-float--1\"><strong>100-bed</strong>attached hospital</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-float sr-float--2\"} -->\n<p class=\"sr-float sr-float--2\"><strong>5</strong>programmes</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div></div>\n<!-- /wp:cover -->\n\n<!-- wp:columns {\"align\":\"wide\",\"className\":\"sr-stats\"} -->\n<div class=\"wp-block-columns alignwide sr-stats\">\n<!-- wp:column {\"className\":\"sr-icon sr-icon--soft ico-bed\"} -->\n<div class=\"wp-block-column sr-icon sr-icon--soft ico-bed\">\n<!-- wp:paragraph {\"className\":\"sr-stat__num\"} -->\n<p class=\"sr-stat__num\">100</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-stat__label\"} -->\n<p class=\"sr-stat__label\">Bed attached hospital</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"sr-icon sr-icon--soft ico-graduation\"} -->\n<div class=\"wp-block-column sr-icon sr-icon--soft ico-graduation\">\n<!-- wp:paragraph {\"className\":\"sr-stat__num\"} -->\n<p class=\"sr-stat__num\">5</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-stat__label\"} -->\n<p class=\"sr-stat__label\">Nursing &amp; paramedical programmes</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"sr-icon sr-icon--soft ico-users\"} -->\n<div class=\"wp-block-column sr-icon sr-icon--soft ico-users\">\n<!-- wp:paragraph {\"className\":\"sr-stat__num\"} -->\n<p class=\"sr-stat__num\">170+</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-stat__label\"} -->\n<p class=\"sr-stat__label\">Approved seats every year</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"sr-icon sr-icon--soft ico-home\"} -->\n<div class=\"wp-block-column sr-icon sr-icon--soft ico-home\">\n<!-- wp:paragraph {\"className\":\"sr-stat__num\"} -->\n<p class=\"sr-stat__num\">2</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-stat__label\"} -->\n<p class=\"sr-stat__label\">Separate hostels for girls &amp; boys</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {\"verticalAlignment\":\"center\",\"align\":\"full\",\"className\":\"sr-split sr-bleed-l\"} -->\n<div class=\"wp-block-columns alignfull are-vertically-aligned-center sr-split sr-bleed-l\">\n<!-- wp:column {\"className\":\"sr-panel sr-panel--teal\"} -->\n<div class=\"wp-block-column sr-panel sr-panel--teal\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Since</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-bignum__n\"} -->\n<p class=\"sr-bignum__n\">2012</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-panel__lead\"} -->\n<p class=\"sr-panel__lead\">A trusted name in nursing education in Mahendragarh district.</p>\n<!-- /wp:paragraph -->\n<!-- wp:list {\"className\":\"sr-icon-list\"} -->\n<ul class=\"wp-block-list sr-icon-list\"><!-- wp:list-item -->\n<li>Approved by the Indian Nursing Council</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Recognised by the Haryana Nurses &amp; Midwives Council</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Affiliated to Pt. B.D. Sharma UHS, Rohtak</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Private, co-educational institution</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"sr-split__text\"} -->\n<div class=\"wp-block-column sr-split__text\">\n<!-- wp:group {\"className\":\"sr-section-head\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-section-head\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">About the college</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Quality nursing education in the heart of rural Haryana</h2>\n<!-- /wp:heading -->\n</div>\n<!-- /wp:group -->\n<!-- wp:paragraph -->\n<p>Shri Ram College of Medical Science &amp; Research at Digrota, Mahendragarh, runs <strong>Shri Ram College of Nursing</strong> and <strong>Shri Ram School of Nursing</strong>, offering degree and diploma programmes in nursing and allied health.</p>\n<!-- /wp:paragraph -->\n<!-- wp:columns {\"className\":\"sr-features\"} -->\n<div class=\"wp-block-columns sr-features\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-feature sr-icon sr-icon--soft ico-hospital\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-feature sr-icon sr-icon--soft ico-hospital\">\n<!-- wp:paragraph -->\n<p><strong>Own 100-bed hospital</strong>Clinical exposure from the early semesters.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"sr-feature sr-icon sr-icon--soft ico-microscope\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-feature sr-icon sr-icon--soft ico-microscope\">\n<!-- wp:paragraph -->\n<p><strong>Modern laboratories</strong>Anatomy, physiology, microbiology &amp; nursing skills.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"sr-feature sr-icon sr-icon--soft ico-book\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-feature sr-icon sr-icon--soft ico-book\">\n<!-- wp:paragraph -->\n<p><strong>Well-stocked library</strong>3,500+ books, journals and e-resources.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-feature sr-icon sr-icon--soft ico-home\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-feature sr-icon sr-icon--soft ico-home\">\n<!-- wp:paragraph -->\n<p><strong>Safe hostels</strong>Separate hostels for girls and boys, with mess.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"sr-feature sr-icon sr-icon--soft ico-bus\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-feature sr-icon sr-icon--soft ico-bus\">\n<!-- wp:paragraph -->\n<p><strong>College transport</strong>Buses on routes around the campus.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"sr-feature sr-icon sr-icon--soft ico-wifi\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-feature sr-icon sr-icon--soft ico-wifi\">\n<!-- wp:paragraph -->\n<p><strong>Wi-Fi campus</strong>Plus a gym, sports complex and canteen.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" href=\"/about/\">More about us</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n\n<!-- wp:group {\"align\":\"full\",\"backgroundColor\":\"light\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1400px\",\"wideSize\":\"1400px\"}} -->\n<div class=\"wp-block-group alignfull has-light-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\">\n<!-- wp:group {\"className\":\"sr-section-head is-centered\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-section-head is-centered\">\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"sr-tag\"} -->\n<p class=\"has-text-align-center sr-tag\">Programmes</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Courses we offer</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Degree and diploma programmes in nursing and allied health sciences.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:columns -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-course sr-icon ico-nurse\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-course sr-icon ico-nurse\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Degree · 4 years</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">B.Sc Nursing</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-meta\"} -->\n<p class=\"sr-meta\">50 seats</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A four-year professional degree that builds a strong foundation in nursing science, anatomy and direct patient care, with extensive hospital practice.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-more\"} -->\n<p class=\"sr-more\"><a href=\"/courses/bsc-nursing/\">View course details</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-course sr-icon ico-graduation\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-course sr-icon ico-graduation\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Degree · 2 years</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Post Basic B.Sc Nursing</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-meta\"} -->\n<p class=\"sr-meta\">40 seats</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A two-year degree for registered GNM nurses who want to upgrade to a B.Sc qualification and take on greater clinical and leadership roles.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-more\"} -->\n<p class=\"sr-more\"><a href=\"/courses/post-basic-bsc-nursing/\">View course details</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-course sr-icon ico-microscope\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-course sr-icon ico-microscope\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Degree · 3 years</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">B.Sc Paramedical Science</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-meta\"} -->\n<p class=\"sr-meta\">50 seats</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A three-year allied-health degree awarded by Pt. B.D. Sharma UHS, Rohtak, preparing technologists for hospital and diagnostic settings.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-more\"} -->\n<p class=\"sr-more\"><a href=\"/courses/bsc-paramedical-science/\">View course details</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n<!-- wp:columns -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-course sr-icon sr-icon--accent ico-stethoscope\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-course sr-icon sr-icon--accent ico-stethoscope\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Diploma · 3 years</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">GNM – General Nursing &amp; Midwifery</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-meta\"} -->\n<p class=\"sr-meta\">Seats as approved</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A diploma programme in general nursing and midwifery, leading to registration as a nurse and midwife with the state council.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-more\"} -->\n<p class=\"sr-more\"><a href=\"/courses/gnm/\">View course details</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-course sr-icon sr-icon--accent ico-heart\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-course sr-icon sr-icon--accent ico-heart\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Diploma · 2 years</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">ANM – Auxiliary Nurse Midwifery</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-meta\"} -->\n<p class=\"sr-meta\">30 seats</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A two-year diploma that trains community health workers in maternal and child health, first aid and primary care.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-more\"} -->\n<p class=\"sr-more\"><a href=\"/courses/anm/\">View course details</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/courses/\">Compare all courses</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"sr-ticker-band\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignfull sr-ticker-band\">\n<!-- wp:html -->\n<div class=\"sr-ticker\" role=\"region\" aria-label=\"Recognition and highlights\"><ul class=\"sr-ticker__track\"><li>INC Approved</li><li>HNRC Recognised</li><li>Affiliated to Pt. B.D. Sharma UHS, Rohtak</li><li>Recognised by Govt. of Haryana</li><li>Own 100-Bed Hospital</li><li>B.Sc Nursing</li><li>Post Basic B.Sc Nursing</li><li>B.Sc Paramedical</li><li>GNM</li><li>ANM</li></ul><ul class=\"sr-ticker__track\" aria-hidden=\"true\"><li>INC Approved</li><li>HNRC Recognised</li><li>Affiliated to Pt. B.D. Sharma UHS, Rohtak</li><li>Recognised by Govt. of Haryana</li><li>Own 100-Bed Hospital</li><li>B.Sc Nursing</li><li>Post Basic B.Sc Nursing</li><li>B.Sc Paramedical</li><li>GNM</li><li>ANM</li></ul></div>\n<!-- /wp:html -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|40\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"680px\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--40)\">\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"sr-tag\"} -->\n<p class=\"has-text-align-center sr-tag\">Life at Shri Ram</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\">A campus built for learning and care</h2>\n<!-- /wp:heading -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"align\":\"full\",\"className\":\"sr-mosaic sr-mosaic--photos\"} -->\n<div class=\"wp-block-columns alignfull sr-mosaic sr-mosaic--photos\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"id\":111,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/students-batch.jpg\" alt=\"A batch of nursing students on the college lawn\" class=\"wp-image-111\"/><figcaption class=\"wp-element-caption\">Photo: DS KNOWLEDGE via Google Maps</figcaption></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"id\":96,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/skill-practice.jpg\" alt=\"Students practising bed making in the nursing skill lab\" class=\"wp-image-96\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"id\":99,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/library-hall.jpg\" alt=\"Spacious library hall with reading tables\" class=\"wp-image-99\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"id\":91,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/hospital-ward.jpg\" alt=\"Hospital ward with beds and screens\" class=\"wp-image-91\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"id\":100,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/classroom-students.jpg\" alt=\"Nursing students attending a lecture\" class=\"wp-image-100\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"sr-dark sr-pillars\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n<div class=\"wp-block-group alignfull sr-dark sr-pillars\" style=\"padding-top:var(--wp--preset--spacing--60)\">\n<!-- wp:group {\"layout\":{\"type\":\"constrained\",\"contentSize\":\"680px\"}} -->\n<div class=\"wp-block-group\">\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"sr-tag\"} -->\n<p class=\"has-text-align-center sr-tag\">Our pillars</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Care. Compassion. Competence.</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Three values that guide how we teach and how our students serve.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:columns {\"align\":\"full\",\"className\":\"sr-tiles\"} -->\n<div class=\"wp-block-columns alignfull sr-tiles\">\n<!-- wp:column {\"className\":\"sr-tile\"} -->\n<div class=\"wp-block-column sr-tile\">\n<!-- wp:group {\"className\":\"sr-pillar sr-icon sr-icon--accent ico-hands\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-pillar sr-icon sr-icon--accent ico-hands\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Care</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Patient-centred nursing is at the heart of everything we teach, from the first classroom lesson to the hospital ward.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"sr-tile\"} -->\n<div class=\"wp-block-column sr-tile\">\n<!-- wp:group {\"className\":\"sr-pillar sr-icon sr-icon--accent ico-heart\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-pillar sr-icon sr-icon--accent ico-heart\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Compassion</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>We shape professionals who treat every patient with dignity, empathy and respect, whatever their background.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"sr-tile\"} -->\n<div class=\"wp-block-column sr-tile\">\n<!-- wp:group {\"className\":\"sr-pillar sr-icon sr-icon--accent ico-award\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-pillar sr-icon sr-icon--accent ico-award\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Competence</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Strong science, supervised clinical practice and professional ethics prepare graduates for real-world healthcare.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"verticalAlignment\":\"center\",\"align\":\"full\",\"className\":\"sr-split sr-bleed-l sr-split--light\"} -->\n<div class=\"wp-block-columns alignfull are-vertically-aligned-center sr-split sr-bleed-l sr-split--light\">\n<!-- wp:column {\"className\":\"sr-panel sr-panel--navy\"} -->\n<div class=\"wp-block-column sr-panel sr-panel--navy\">\n<!-- wp:image {\"id\":87,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"sr-panel-photo\"} -->\n<figure class=\"wp-block-image size-full sr-panel-photo\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/hospital-building.jpg\" alt=\"Shri Ram Hospital building on the college campus\" class=\"wp-image-87\"/></figure>\n<!-- /wp:image -->\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Clinical training</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-bignum__n\"} -->\n<p class=\"sr-bignum__n\">100</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">bed hospital on our own campus</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Students learn at the bedside under supervision, rotating through wards and services, alongside community health postings in the surrounding villages.</p>\n<!-- /wp:paragraph -->\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/hospital/\">About the hospital</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"sr-split__text\"} -->\n<div class=\"wp-block-column sr-split__text\">\n<!-- wp:group {\"className\":\"sr-section-head\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-section-head\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Campus life</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Everything you need on one campus</h2>\n<!-- /wp:heading -->\n</div>\n<!-- /wp:group -->\n<!-- wp:columns -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-icon--sm sr-icon sr-icon--soft ico-monitor\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-icon--sm sr-icon sr-icon--soft ico-monitor\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Classrooms</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Spacious halls with audio-visual aids.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"sr-card sr-icon--sm sr-icon sr-icon--soft ico-stage\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-icon--sm sr-icon sr-icon--soft ico-stage\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Auditorium</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Seminars, workshops and events.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-icon--sm sr-icon sr-icon--soft ico-flask\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-icon--sm sr-icon sr-icon--soft ico-flask\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Skill labs</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Hands-on practice before the ward.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"sr-card sr-icon--sm sr-icon sr-icon--soft ico-utensils\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-icon--sm sr-icon sr-icon--soft ico-utensils\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Canteen &amp; gym</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Hygienic food, fitness and sports.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n<!-- wp:paragraph {\"className\":\"sr-more\"} -->\n<p class=\"sr-more\"><a href=\"/campus-facilities/\">Explore all facilities</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"960px\",\"wideSize\":\"960px\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\">\n<!-- wp:group {\"className\":\"sr-section-head is-centered\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-section-head is-centered\">\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"sr-tag\"} -->\n<p class=\"has-text-align-center sr-tag\">Admissions</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Your path to a nursing career</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Admissions follow the rules of DMER Haryana and Pt. B.D. Sharma UHS, Rohtak.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:columns {\"className\":\"sr-steps\"} -->\n<div class=\"wp-block-columns sr-steps\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-step\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-step\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Check eligibility</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>10+2 with the required subjects and marks; minimum age 17 by 31 December.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-step\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-step\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Apply / appear</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>B.Sc courses: UHSR entrance test &amp; counselling. ANM/GNM: merit-based.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-step\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-step\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Choose Shri Ram</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Select Shri Ram College of Nursing, Digrota, in counselling, or contact us.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-step\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-step\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Report &amp; enrol</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Bring original documents, pay the fee and begin your journey.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/admissions/\">Admission details</a></div>\n<!-- /wp:button --><!-- wp:button {\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" href=\"/fee-structure/\">Fee structure</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"verticalAlignment\":\"center\",\"align\":\"full\",\"className\":\"sr-split sr-bleed-r\"} -->\n<div class=\"wp-block-columns alignfull are-vertically-aligned-center sr-split sr-bleed-r\">\n<!-- wp:column {\"className\":\"sr-split__text\"} -->\n<div class=\"wp-block-column sr-split__text\">\n<!-- wp:group {\"className\":\"sr-section-head\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-section-head\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Latest</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Notices &amp; announcements</h2>\n<!-- /wp:heading -->\n</div>\n<!-- /wp:group -->\n<!-- wp:query {\"queryId\":2,\"query\":{\"perPage\":3,\"postType\":\"post\",\"order\":\"desc\",\"orderBy\":\"date\",\"inherit\":false},\"className\":\"sr-notices\"} -->\n<div class=\"wp-block-query sr-notices\">\n<!-- wp:post-template -->\n<!-- wp:post-date {\"fontSize\":\"small\"} /-->\n<!-- wp:post-title {\"isLink\":true,\"level\":3} /-->\n<!-- /wp:post-template -->\n<!-- wp:query-no-results -->\n<!-- wp:paragraph -->\n<p>New notices will appear here.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:query-no-results -->\n</div>\n<!-- /wp:query -->\n<!-- wp:paragraph {\"className\":\"sr-more\"} -->\n<p class=\"sr-more\"><a href=\"/notices/\">All notices</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"sr-panel sr-panel--cta sr-icon sr-icon--accent ico-lamp\"} -->\n<div class=\"wp-block-column sr-panel sr-panel--cta sr-icon sr-icon--accent ico-lamp\">\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Begin your career in healthcare</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Talk to our admissions team about courses, eligibility, fees and hostel availability.</p>\n<!-- /wp:paragraph -->\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/contact/\">Contact Admissions</a></div>\n<!-- /wp:button --><!-- wp:button {\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" href=\"/admissions/\">Admission Process</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n','Home','','inherit','closed','closed','','7-revision-v1','','','2026-09-26 20:46:28','2026-09-26 15:16:28','',7,'http://localhost:8092/?p=124',0,'revision','',0),
(125,0,'2026-09-26 20:55:22','2026-09-26 15:25:22','<!-- wp:cover {\"url\":\"http://localhost:8092/wp-content/uploads/2026/09/campus-wide.jpg\",\"id\":85,\"dimRatio\":90,\"overlayColor\":\"dark\",\"isDark\":true,\"align\":\"full\",\"className\":\"sr-hero\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n<div class=\"wp-block-cover alignfull is-dark sr-hero\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-dark-background-color has-background-dim-90 has-background-dim\"></span><img class=\"wp-block-cover__image-background wp-image-85\" alt=\"\" src=\"http://localhost:8092/wp-content/uploads/2026/09/campus-wide.jpg\" data-object-fit=\"cover\"/><div class=\"wp-block-cover__inner-container\">\n<!-- wp:columns {\"verticalAlignment\":\"center\",\"align\":\"full\",\"className\":\"sr-split sr-bleed-r sr-hero-cols\"} -->\n<div class=\"wp-block-columns alignfull are-vertically-aligned-center sr-split sr-bleed-r sr-hero-cols\">\n<!-- wp:column {\"className\":\"sr-hero-text\"} -->\n<div class=\"wp-block-column sr-hero-text\">\n<!-- wp:paragraph {\"className\":\"sr-eyebrow\"} -->\n<p class=\"sr-eyebrow\">Digrota · Satnali · Mahendragarh · Haryana</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":1} -->\n<h1 class=\"wp-block-heading\">Shaping skilled, <em>compassionate</em> nurses &amp; healthcare professionals</h1>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-lead\"} -->\n<p class=\"sr-lead\">Nursing and paramedical programmes approved by the Indian Nursing Council and affiliated to Pt. B.D. Sharma University of Health Sciences, Rohtak, with hands-on clinical training at our own 100-bed hospital.</p>\n<!-- /wp:paragraph -->\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/admissions/\">Apply for Admission</a></div>\n<!-- /wp:button --><!-- wp:button {\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" href=\"/courses/\">Explore Courses</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n<!-- wp:group {\"className\":\"sr-badges\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\"}} -->\n<div class=\"wp-block-group sr-badges\">\n<!-- wp:paragraph -->\n<p>✓ INC Approved</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>✓ HNRC Recognised</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>✓ UHSR Rohtak Affiliated</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"sr-hero-art\"} -->\n<div class=\"wp-block-column sr-hero-art\">\n<!-- wp:image {\"sizeSlug\":\"full\",\"className\":\"sr-hero-img\"} -->\n<figure class=\"wp-block-image size-full sr-hero-img\"><img src=\"http://localhost:8092/wp-content/themes/shriram-college/assets/images/hero-illustration.svg\" alt=\"Illustration of the college hospital with a heartbeat line\"/></figure>\n<!-- /wp:image -->\n<!-- wp:paragraph {\"className\":\"sr-float sr-float--1\"} -->\n<p class=\"sr-float sr-float--1\"><strong>100-bed</strong>attached hospital</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-float sr-float--2\"} -->\n<p class=\"sr-float sr-float--2\"><strong>5</strong>programmes</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div></div>\n<!-- /wp:cover -->\n\n<!-- wp:columns {\"align\":\"wide\",\"className\":\"sr-stats\"} -->\n<div class=\"wp-block-columns alignwide sr-stats\">\n<!-- wp:column {\"className\":\"sr-icon sr-icon--soft ico-bed\"} -->\n<div class=\"wp-block-column sr-icon sr-icon--soft ico-bed\">\n<!-- wp:paragraph {\"className\":\"sr-stat__num\"} -->\n<p class=\"sr-stat__num\">100</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-stat__label\"} -->\n<p class=\"sr-stat__label\">Bed attached hospital</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"sr-icon sr-icon--soft ico-graduation\"} -->\n<div class=\"wp-block-column sr-icon sr-icon--soft ico-graduation\">\n<!-- wp:paragraph {\"className\":\"sr-stat__num\"} -->\n<p class=\"sr-stat__num\">5</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-stat__label\"} -->\n<p class=\"sr-stat__label\">Nursing &amp; paramedical programmes</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"sr-icon sr-icon--soft ico-users\"} -->\n<div class=\"wp-block-column sr-icon sr-icon--soft ico-users\">\n<!-- wp:paragraph {\"className\":\"sr-stat__num\"} -->\n<p class=\"sr-stat__num\">170+</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-stat__label\"} -->\n<p class=\"sr-stat__label\">Approved seats every year</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"sr-icon sr-icon--soft ico-home\"} -->\n<div class=\"wp-block-column sr-icon sr-icon--soft ico-home\">\n<!-- wp:paragraph {\"className\":\"sr-stat__num\"} -->\n<p class=\"sr-stat__num\">2</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-stat__label\"} -->\n<p class=\"sr-stat__label\">Separate hostels for girls &amp; boys</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {\"verticalAlignment\":\"center\",\"align\":\"full\",\"className\":\"sr-split sr-bleed-l\"} -->\n<div class=\"wp-block-columns alignfull are-vertically-aligned-center sr-split sr-bleed-l\">\n<!-- wp:column {\"className\":\"sr-panel sr-panel--teal\"} -->\n<div class=\"wp-block-column sr-panel sr-panel--teal\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Since</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-bignum__n\"} -->\n<p class=\"sr-bignum__n\">2012</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-panel__lead\"} -->\n<p class=\"sr-panel__lead\">A trusted name in nursing education in Mahendragarh district.</p>\n<!-- /wp:paragraph -->\n<!-- wp:list {\"className\":\"sr-icon-list\"} -->\n<ul class=\"wp-block-list sr-icon-list\"><!-- wp:list-item -->\n<li>Approved by the Indian Nursing Council</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Recognised by the Haryana Nurses &amp; Midwives Council</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Affiliated to Pt. B.D. Sharma UHS, Rohtak</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Private, co-educational institution</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"sr-split__text\"} -->\n<div class=\"wp-block-column sr-split__text\">\n<!-- wp:group {\"className\":\"sr-section-head\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-section-head\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">About the college</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Quality nursing education in the heart of rural Haryana</h2>\n<!-- /wp:heading -->\n</div>\n<!-- /wp:group -->\n<!-- wp:paragraph -->\n<p>Shri Ram College of Medical Science &amp; Research at Digrota, Mahendragarh, runs <strong>Shri Ram College of Nursing</strong> and <strong>Shri Ram School of Nursing</strong>, offering degree and diploma programmes in nursing and allied health.</p>\n<!-- /wp:paragraph -->\n<!-- wp:columns {\"className\":\"sr-features\"} -->\n<div class=\"wp-block-columns sr-features\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-feature sr-icon sr-icon--soft ico-hospital\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-feature sr-icon sr-icon--soft ico-hospital\">\n<!-- wp:paragraph -->\n<p><strong>Own 100-bed hospital</strong>Clinical exposure from the early semesters.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"sr-feature sr-icon sr-icon--soft ico-microscope\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-feature sr-icon sr-icon--soft ico-microscope\">\n<!-- wp:paragraph -->\n<p><strong>Modern laboratories</strong>Anatomy, physiology, microbiology &amp; nursing skills.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"sr-feature sr-icon sr-icon--soft ico-book\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-feature sr-icon sr-icon--soft ico-book\">\n<!-- wp:paragraph -->\n<p><strong>Well-stocked library</strong>3,500+ books, journals and e-resources.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-feature sr-icon sr-icon--soft ico-home\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-feature sr-icon sr-icon--soft ico-home\">\n<!-- wp:paragraph -->\n<p><strong>Safe hostels</strong>Separate hostels for girls and boys, with mess.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"sr-feature sr-icon sr-icon--soft ico-bus\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-feature sr-icon sr-icon--soft ico-bus\">\n<!-- wp:paragraph -->\n<p><strong>College transport</strong>Buses on routes around the campus.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"sr-feature sr-icon sr-icon--soft ico-wifi\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-feature sr-icon sr-icon--soft ico-wifi\">\n<!-- wp:paragraph -->\n<p><strong>Wi-Fi campus</strong>Plus a gym, sports complex and canteen.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" href=\"/about/\">More about us</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"sr-courses\",\"backgroundColor\":\"light\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1400px\",\"wideSize\":\"1400px\"}} -->\n<div class=\"wp-block-group alignfull sr-courses has-light-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\">\n<!-- wp:group {\"className\":\"sr-courses-head\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"space-between\",\"verticalAlignment\":\"bottom\"}} -->\n<div class=\"wp-block-group sr-courses-head\">\n<!-- wp:group {\"className\":\"sr-section-head\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-section-head\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Programmes</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Courses we offer</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Degree and diploma programmes in nursing and allied health sciences, with clinical training in our own hospital.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:html -->\n<div class=\"sr-filter\" role=\"group\" aria-label=\"Filter programmes\"><button type=\"button\" class=\"is-active\" data-filter=\"all\" aria-pressed=\"true\">All programmes</button><button type=\"button\" data-filter=\"degree\" aria-pressed=\"false\">Degrees</button><button type=\"button\" data-filter=\"diploma\" aria-pressed=\"false\">Diplomas</button></div>\n<!-- /wp:html -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"sr-bento\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-bento\">\n<!-- wp:group {\"className\":\"sr-course-card sr-kind-degree\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-course-card sr-kind-degree\">\n<!-- wp:image {\"id\":96,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"sr-course-card__img\"} -->\n<figure class=\"wp-block-image size-full sr-course-card__img\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/skill-practice.jpg\" alt=\"Students practising bed making in the nursing skill lab\" class=\"wp-image-96\"/></figure>\n<!-- /wp:image -->\n<!-- wp:group {\"className\":\"sr-course-card__body sr-icon ico-nurse\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-course-card__body sr-icon ico-nurse\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Degree programme</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">B.Sc Nursing</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-chips\"} -->\n<p class=\"sr-chips\"><span class=\"sr-chip sr-chip--time\">4 years</span><span class=\"sr-chip sr-chip--seats\">50 seats</span></p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A four-year professional degree that builds a strong foundation in nursing science, anatomy and direct patient care, with extensive hospital practice.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-more\"} -->\n<p class=\"sr-more\"><a href=\"/courses/bsc-nursing/\">View course details</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"sr-course-card sr-kind-degree\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-course-card sr-kind-degree\">\n<!-- wp:image {\"id\":92,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"sr-course-card__img\"} -->\n<figure class=\"wp-block-image size-full sr-course-card__img\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/hospital-ward-2.jpg\" alt=\"Demonstration ward with hospital beds\" class=\"wp-image-92\"/></figure>\n<!-- /wp:image -->\n<!-- wp:group {\"className\":\"sr-course-card__body sr-icon ico-graduation\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-course-card__body sr-icon ico-graduation\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Degree programme</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Post Basic B.Sc Nursing</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-chips\"} -->\n<p class=\"sr-chips\"><span class=\"sr-chip sr-chip--time\">2 years</span><span class=\"sr-chip sr-chip--seats\">40 seats</span></p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A two-year degree for registered GNM nurses who want to upgrade to a B.Sc qualification and take on greater clinical and leadership roles.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-more\"} -->\n<p class=\"sr-more\"><a href=\"/courses/post-basic-bsc-nursing/\">View course details</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"sr-course-card sr-kind-degree\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-course-card sr-kind-degree\">\n<!-- wp:image {\"id\":108,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"sr-course-card__img\"} -->\n<figure class=\"wp-block-image size-full sr-course-card__img\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/lab-hall.jpg\" alt=\"Pre-clinical lab hall with charts and models\" class=\"wp-image-108\"/></figure>\n<!-- /wp:image -->\n<!-- wp:group {\"className\":\"sr-course-card__body sr-icon ico-microscope\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-course-card__body sr-icon ico-microscope\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Degree programme</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">B.Sc Paramedical Science</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-chips\"} -->\n<p class=\"sr-chips\"><span class=\"sr-chip sr-chip--time\">3 years</span><span class=\"sr-chip sr-chip--seats\">50 seats</span></p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A three-year allied-health degree awarded by Pt. B.D. Sharma UHS, Rohtak, preparing technologists for hospital and diagnostic settings.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-more\"} -->\n<p class=\"sr-more\"><a href=\"/courses/bsc-paramedical-science/\">View course details</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"sr-course-card sr-kind-diploma\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-course-card sr-kind-diploma\">\n<!-- wp:image {\"id\":95,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"sr-course-card__img\"} -->\n<figure class=\"wp-block-image size-full sr-course-card__img\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/nursing-foundation-lab.jpg\" alt=\"Nursing foundation lab with beds and wheelchair\" class=\"wp-image-95\"/></figure>\n<!-- /wp:image -->\n<!-- wp:group {\"className\":\"sr-course-card__body sr-icon sr-icon--accent ico-stethoscope\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-course-card__body sr-icon sr-icon--accent ico-stethoscope\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Diploma programme</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">GNM – General Nursing &amp; Midwifery</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-chips\"} -->\n<p class=\"sr-chips\"><span class=\"sr-chip sr-chip--time\">3 years</span><span class=\"sr-chip sr-chip--seats\">Seats as approved</span></p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A diploma programme in general nursing and midwifery, leading to registration as a nurse and midwife with the state council.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-more\"} -->\n<p class=\"sr-more\"><a href=\"/courses/gnm/\">View course details</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"sr-course-card sr-kind-diploma\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-course-card sr-kind-diploma\">\n<!-- wp:image {\"id\":94,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"sr-course-card__img\"} -->\n<figure class=\"wp-block-image size-full sr-course-card__img\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/maternity-room.jpg\" alt=\"Examination room with delivery table\" class=\"wp-image-94\"/></figure>\n<!-- /wp:image -->\n<!-- wp:group {\"className\":\"sr-course-card__body sr-icon sr-icon--accent ico-heart\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-course-card__body sr-icon sr-icon--accent ico-heart\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Diploma programme</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">ANM – Auxiliary Nurse Midwifery</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-chips\"} -->\n<p class=\"sr-chips\"><span class=\"sr-chip sr-chip--time\">2 years</span><span class=\"sr-chip sr-chip--seats\">30 seats</span></p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A two-year diploma that trains community health workers in maternal and child health, first aid and primary care.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-more\"} -->\n<p class=\"sr-more\"><a href=\"/courses/anm/\">View course details</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"sr-more\"} -->\n<p class=\"has-text-align-center sr-more\"><a href=\"/courses/\">Compare all courses side by side</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"sr-ticker-band\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignfull sr-ticker-band\">\n<!-- wp:html -->\n<div class=\"sr-ticker\" role=\"region\" aria-label=\"Recognition and highlights\"><ul class=\"sr-ticker__track\"><li>INC Approved</li><li>HNRC Recognised</li><li>Affiliated to Pt. B.D. Sharma UHS, Rohtak</li><li>Recognised by Govt. of Haryana</li><li>Own 100-Bed Hospital</li><li>B.Sc Nursing</li><li>Post Basic B.Sc Nursing</li><li>B.Sc Paramedical</li><li>GNM</li><li>ANM</li></ul><ul class=\"sr-ticker__track\" aria-hidden=\"true\"><li>INC Approved</li><li>HNRC Recognised</li><li>Affiliated to Pt. B.D. Sharma UHS, Rohtak</li><li>Recognised by Govt. of Haryana</li><li>Own 100-Bed Hospital</li><li>B.Sc Nursing</li><li>Post Basic B.Sc Nursing</li><li>B.Sc Paramedical</li><li>GNM</li><li>ANM</li></ul></div>\n<!-- /wp:html -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|40\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"680px\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--40)\">\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"sr-tag\"} -->\n<p class=\"has-text-align-center sr-tag\">Life at Shri Ram</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\">A campus built for learning and care</h2>\n<!-- /wp:heading -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"align\":\"full\",\"className\":\"sr-mosaic sr-mosaic--photos\"} -->\n<div class=\"wp-block-columns alignfull sr-mosaic sr-mosaic--photos\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"id\":111,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/students-batch.jpg\" alt=\"A batch of nursing students on the college lawn\" class=\"wp-image-111\"/><figcaption class=\"wp-element-caption\">Photo: DS KNOWLEDGE via Google Maps</figcaption></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"id\":96,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/skill-practice.jpg\" alt=\"Students practising bed making in the nursing skill lab\" class=\"wp-image-96\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"id\":99,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/library-hall.jpg\" alt=\"Spacious library hall with reading tables\" class=\"wp-image-99\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"id\":91,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/hospital-ward.jpg\" alt=\"Hospital ward with beds and screens\" class=\"wp-image-91\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"id\":100,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/classroom-students.jpg\" alt=\"Nursing students attending a lecture\" class=\"wp-image-100\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"sr-dark sr-pillars\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n<div class=\"wp-block-group alignfull sr-dark sr-pillars\" style=\"padding-top:var(--wp--preset--spacing--60)\">\n<!-- wp:group {\"layout\":{\"type\":\"constrained\",\"contentSize\":\"680px\"}} -->\n<div class=\"wp-block-group\">\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"sr-tag\"} -->\n<p class=\"has-text-align-center sr-tag\">Our pillars</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Care. Compassion. Competence.</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Three values that guide how we teach and how our students serve.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:columns {\"align\":\"full\",\"className\":\"sr-tiles\"} -->\n<div class=\"wp-block-columns alignfull sr-tiles\">\n<!-- wp:column {\"className\":\"sr-tile\"} -->\n<div class=\"wp-block-column sr-tile\">\n<!-- wp:group {\"className\":\"sr-pillar sr-icon sr-icon--accent ico-hands\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-pillar sr-icon sr-icon--accent ico-hands\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Care</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Patient-centred nursing is at the heart of everything we teach, from the first classroom lesson to the hospital ward.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"sr-tile\"} -->\n<div class=\"wp-block-column sr-tile\">\n<!-- wp:group {\"className\":\"sr-pillar sr-icon sr-icon--accent ico-heart\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-pillar sr-icon sr-icon--accent ico-heart\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Compassion</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>We shape professionals who treat every patient with dignity, empathy and respect, whatever their background.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"sr-tile\"} -->\n<div class=\"wp-block-column sr-tile\">\n<!-- wp:group {\"className\":\"sr-pillar sr-icon sr-icon--accent ico-award\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-pillar sr-icon sr-icon--accent ico-award\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Competence</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Strong science, supervised clinical practice and professional ethics prepare graduates for real-world healthcare.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"verticalAlignment\":\"center\",\"align\":\"full\",\"className\":\"sr-split sr-bleed-l sr-split--light\"} -->\n<div class=\"wp-block-columns alignfull are-vertically-aligned-center sr-split sr-bleed-l sr-split--light\">\n<!-- wp:column {\"className\":\"sr-panel sr-panel--navy\"} -->\n<div class=\"wp-block-column sr-panel sr-panel--navy\">\n<!-- wp:image {\"id\":87,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"sr-panel-photo\"} -->\n<figure class=\"wp-block-image size-full sr-panel-photo\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/hospital-building.jpg\" alt=\"Shri Ram Hospital building on the college campus\" class=\"wp-image-87\"/></figure>\n<!-- /wp:image -->\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Clinical training</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-bignum__n\"} -->\n<p class=\"sr-bignum__n\">100</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">bed hospital on our own campus</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Students learn at the bedside under supervision, rotating through wards and services, alongside community health postings in the surrounding villages.</p>\n<!-- /wp:paragraph -->\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/hospital/\">About the hospital</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"sr-split__text\"} -->\n<div class=\"wp-block-column sr-split__text\">\n<!-- wp:group {\"className\":\"sr-section-head\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-section-head\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Campus life</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Everything you need on one campus</h2>\n<!-- /wp:heading -->\n</div>\n<!-- /wp:group -->\n<!-- wp:columns -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-icon--sm sr-icon sr-icon--soft ico-monitor\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-icon--sm sr-icon sr-icon--soft ico-monitor\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Classrooms</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Spacious halls with audio-visual aids.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"sr-card sr-icon--sm sr-icon sr-icon--soft ico-stage\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-icon--sm sr-icon sr-icon--soft ico-stage\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Auditorium</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Seminars, workshops and events.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-card sr-icon--sm sr-icon sr-icon--soft ico-flask\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-icon--sm sr-icon sr-icon--soft ico-flask\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Skill labs</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Hands-on practice before the ward.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"sr-card sr-icon--sm sr-icon sr-icon--soft ico-utensils\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-card sr-icon--sm sr-icon sr-icon--soft ico-utensils\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Canteen &amp; gym</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Hygienic food, fitness and sports.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n<!-- wp:paragraph {\"className\":\"sr-more\"} -->\n<p class=\"sr-more\"><a href=\"/campus-facilities/\">Explore all facilities</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"960px\",\"wideSize\":\"960px\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\">\n<!-- wp:group {\"className\":\"sr-section-head is-centered\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-section-head is-centered\">\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"sr-tag\"} -->\n<p class=\"has-text-align-center sr-tag\">Admissions</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Your path to a nursing career</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Admissions follow the rules of DMER Haryana and Pt. B.D. Sharma UHS, Rohtak.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:columns {\"className\":\"sr-steps\"} -->\n<div class=\"wp-block-columns sr-steps\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-step\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-step\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Check eligibility</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>10+2 with the required subjects and marks; minimum age 17 by 31 December.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-step\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-step\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Apply / appear</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>B.Sc courses: UHSR entrance test &amp; counselling. ANM/GNM: merit-based.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-step\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-step\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Choose Shri Ram</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Select Shri Ram College of Nursing, Digrota, in counselling, or contact us.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"sr-step\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group sr-step\">\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Report &amp; enrol</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Bring original documents, pay the fee and begin your journey.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/admissions/\">Admission details</a></div>\n<!-- /wp:button --><!-- wp:button {\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" href=\"/fee-structure/\">Fee structure</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"verticalAlignment\":\"center\",\"align\":\"full\",\"className\":\"sr-split sr-bleed-r\"} -->\n<div class=\"wp-block-columns alignfull are-vertically-aligned-center sr-split sr-bleed-r\">\n<!-- wp:column {\"className\":\"sr-split__text\"} -->\n<div class=\"wp-block-column sr-split__text\">\n<!-- wp:group {\"className\":\"sr-section-head\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-section-head\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Latest</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Notices &amp; announcements</h2>\n<!-- /wp:heading -->\n</div>\n<!-- /wp:group -->\n<!-- wp:query {\"queryId\":2,\"query\":{\"perPage\":3,\"postType\":\"post\",\"order\":\"desc\",\"orderBy\":\"date\",\"inherit\":false},\"className\":\"sr-notices\"} -->\n<div class=\"wp-block-query sr-notices\">\n<!-- wp:post-template -->\n<!-- wp:post-date {\"fontSize\":\"small\"} /-->\n<!-- wp:post-title {\"isLink\":true,\"level\":3} /-->\n<!-- /wp:post-template -->\n<!-- wp:query-no-results -->\n<!-- wp:paragraph -->\n<p>New notices will appear here.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:query-no-results -->\n</div>\n<!-- /wp:query -->\n<!-- wp:paragraph {\"className\":\"sr-more\"} -->\n<p class=\"sr-more\"><a href=\"/notices/\">All notices</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"sr-panel sr-panel--cta sr-icon sr-icon--accent ico-lamp\"} -->\n<div class=\"wp-block-column sr-panel sr-panel--cta sr-icon sr-icon--accent ico-lamp\">\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Begin your career in healthcare</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Talk to our admissions team about courses, eligibility, fees and hostel availability.</p>\n<!-- /wp:paragraph -->\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/contact/\">Contact Admissions</a></div>\n<!-- /wp:button --><!-- wp:button {\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" href=\"/admissions/\">Admission Process</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n','Home','','inherit','closed','closed','','7-revision-v1','','','2026-09-26 20:55:22','2026-09-26 15:25:22','',7,'http://localhost:8092/?p=125',0,'revision','',0),
(126,0,'2026-09-26 20:55:22','2026-09-26 15:25:22','<!-- wp:paragraph {\"className\":\"has-large-font-size\"} -->\n<p class=\"has-large-font-size\">We offer degree and diploma programmes in nursing and allied health sciences. All nursing programmes are approved by the Indian Nursing Council and the Haryana Nurses &amp; Midwives Council. Degrees are awarded by Pt. B.D. Sharma University of Health Sciences, Rohtak.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|50\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignwide\" style=\"margin-top:var(--wp--preset--spacing--50)\">\n<!-- wp:table -->\n<figure class=\"wp-block-table\"><table><thead><tr><th>Programme</th><th>Level</th><th>Duration</th><th>Seats</th><th>Minimum qualification</th></tr></thead><tbody><tr><td><a href=\"/courses/bsc-nursing/\">B.Sc Nursing</a></td><td>UG Degree</td><td>4 years</td><td>50</td><td>10+2 with PCB &amp; English (50%)</td></tr><tr><td><a href=\"/courses/post-basic-bsc-nursing/\">Post Basic B.Sc Nursing</a></td><td>UG Degree</td><td>2 years</td><td>40</td><td>10+2 + GNM, registered nurse &amp; midwife</td></tr><tr><td><a href=\"/courses/bsc-paramedical-science/\">B.Sc Paramedical Science</a></td><td>UG Degree</td><td>3 years</td><td>50</td><td>10+2 with Science</td></tr><tr><td><a href=\"/courses/gnm/\">GNM</a></td><td>Diploma</td><td>3 years</td><td>As approved</td><td>10+2 (any stream)</td></tr><tr><td><a href=\"/courses/anm/\">ANM</a></td><td>Diploma</td><td>2 years</td><td>30</td><td>10+2 (any stream)</td></tr><tr><td>BAMS (Ayurveda) *</td><td>UG Degree</td><td>5½ years</td><td>—</td><td>10+2 with PCB + NEET</td></tr></tbody></table><figcaption class=\"wp-element-caption\">* BAMS is offered by Shri Ram Ayurvedic Medical College &amp; Hospital on the same campus (CCIM / Ministry of AYUSH; Shri Krishna AYUSH University, Kurukshetra). Seat numbers are the approved intake published by the regulators and may change each session.</figcaption></figure>\n<!-- /wp:table -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"sr-courses\",\"backgroundColor\":\"light\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1400px\",\"wideSize\":\"1400px\"}} -->\n<div class=\"wp-block-group alignfull sr-courses has-light-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\">\n<!-- wp:group {\"className\":\"sr-courses-head\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"space-between\",\"verticalAlignment\":\"bottom\"}} -->\n<div class=\"wp-block-group sr-courses-head\">\n<!-- wp:group {\"className\":\"sr-section-head\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-section-head\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Programmes</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Explore each course</h2>\n<!-- /wp:heading -->\n</div>\n<!-- /wp:group -->\n<!-- wp:html -->\n<div class=\"sr-filter\" role=\"group\" aria-label=\"Filter programmes\"><button type=\"button\" class=\"is-active\" data-filter=\"all\" aria-pressed=\"true\">All programmes</button><button type=\"button\" data-filter=\"degree\" aria-pressed=\"false\">Degrees</button><button type=\"button\" data-filter=\"diploma\" aria-pressed=\"false\">Diplomas</button></div>\n<!-- /wp:html -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"sr-bento\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-bento\">\n<!-- wp:group {\"className\":\"sr-course-card sr-kind-degree\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-course-card sr-kind-degree\">\n<!-- wp:image {\"id\":96,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"sr-course-card__img\"} -->\n<figure class=\"wp-block-image size-full sr-course-card__img\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/skill-practice.jpg\" alt=\"Students practising bed making in the nursing skill lab\" class=\"wp-image-96\"/></figure>\n<!-- /wp:image -->\n<!-- wp:group {\"className\":\"sr-course-card__body sr-icon ico-nurse\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-course-card__body sr-icon ico-nurse\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Degree programme</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">B.Sc Nursing</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-chips\"} -->\n<p class=\"sr-chips\"><span class=\"sr-chip sr-chip--time\">4 years</span><span class=\"sr-chip sr-chip--seats\">50 seats</span></p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A four-year professional degree that builds a strong foundation in nursing science, anatomy and direct patient care, with extensive hospital practice.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-more\"} -->\n<p class=\"sr-more\"><a href=\"/courses/bsc-nursing/\">View course details</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"sr-course-card sr-kind-degree\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-course-card sr-kind-degree\">\n<!-- wp:image {\"id\":92,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"sr-course-card__img\"} -->\n<figure class=\"wp-block-image size-full sr-course-card__img\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/hospital-ward-2.jpg\" alt=\"Demonstration ward with hospital beds\" class=\"wp-image-92\"/></figure>\n<!-- /wp:image -->\n<!-- wp:group {\"className\":\"sr-course-card__body sr-icon ico-graduation\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-course-card__body sr-icon ico-graduation\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Degree programme</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Post Basic B.Sc Nursing</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-chips\"} -->\n<p class=\"sr-chips\"><span class=\"sr-chip sr-chip--time\">2 years</span><span class=\"sr-chip sr-chip--seats\">40 seats</span></p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A two-year degree for registered GNM nurses who want to upgrade to a B.Sc qualification and take on greater clinical and leadership roles.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-more\"} -->\n<p class=\"sr-more\"><a href=\"/courses/post-basic-bsc-nursing/\">View course details</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"sr-course-card sr-kind-degree\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-course-card sr-kind-degree\">\n<!-- wp:image {\"id\":108,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"sr-course-card__img\"} -->\n<figure class=\"wp-block-image size-full sr-course-card__img\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/lab-hall.jpg\" alt=\"Pre-clinical lab hall with charts and models\" class=\"wp-image-108\"/></figure>\n<!-- /wp:image -->\n<!-- wp:group {\"className\":\"sr-course-card__body sr-icon ico-microscope\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-course-card__body sr-icon ico-microscope\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Degree programme</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">B.Sc Paramedical Science</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-chips\"} -->\n<p class=\"sr-chips\"><span class=\"sr-chip sr-chip--time\">3 years</span><span class=\"sr-chip sr-chip--seats\">50 seats</span></p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A three-year allied-health degree awarded by Pt. B.D. Sharma UHS, Rohtak, preparing technologists for hospital and diagnostic settings.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-more\"} -->\n<p class=\"sr-more\"><a href=\"/courses/bsc-paramedical-science/\">View course details</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"sr-course-card sr-kind-diploma\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-course-card sr-kind-diploma\">\n<!-- wp:image {\"id\":95,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"sr-course-card__img\"} -->\n<figure class=\"wp-block-image size-full sr-course-card__img\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/nursing-foundation-lab.jpg\" alt=\"Nursing foundation lab with beds and wheelchair\" class=\"wp-image-95\"/></figure>\n<!-- /wp:image -->\n<!-- wp:group {\"className\":\"sr-course-card__body sr-icon sr-icon--accent ico-stethoscope\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-course-card__body sr-icon sr-icon--accent ico-stethoscope\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Diploma programme</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">GNM – General Nursing &amp; Midwifery</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-chips\"} -->\n<p class=\"sr-chips\"><span class=\"sr-chip sr-chip--time\">3 years</span><span class=\"sr-chip sr-chip--seats\">Seats as approved</span></p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A diploma programme in general nursing and midwifery, leading to registration as a nurse and midwife with the state council.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-more\"} -->\n<p class=\"sr-more\"><a href=\"/courses/gnm/\">View course details</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"sr-course-card sr-kind-diploma\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-course-card sr-kind-diploma\">\n<!-- wp:image {\"id\":94,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"sr-course-card__img\"} -->\n<figure class=\"wp-block-image size-full sr-course-card__img\"><img src=\"http://localhost:8092/wp-content/uploads/2026/09/maternity-room.jpg\" alt=\"Examination room with delivery table\" class=\"wp-image-94\"/></figure>\n<!-- /wp:image -->\n<!-- wp:group {\"className\":\"sr-course-card__body sr-icon sr-icon--accent ico-heart\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group sr-course-card__body sr-icon sr-icon--accent ico-heart\">\n<!-- wp:paragraph {\"className\":\"sr-tag\"} -->\n<p class=\"sr-tag\">Diploma programme</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">ANM – Auxiliary Nurse Midwifery</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"sr-chips\"} -->\n<p class=\"sr-chips\"><span class=\"sr-chip sr-chip--time\">2 years</span><span class=\"sr-chip sr-chip--seats\">30 seats</span></p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A two-year diploma that trains community health workers in maternal and child health, first aid and primary care.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"sr-more\"} -->\n<p class=\"sr-more\"><a href=\"/courses/anm/\">View course details</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"sr-dark sr-cta-band\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"680px\"}} -->\n<div class=\"wp-block-group alignfull sr-dark sr-cta-band\" style=\"padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\">\n<!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Not sure which course fits you?</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Our admissions team can guide you on eligibility, seats and career paths.</p>\n<!-- /wp:paragraph -->\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/contact/\">Talk to admissions</a></div>\n<!-- /wp:button --><!-- wp:button {\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" href=\"/admissions/\">Admission process</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n</div>\n<!-- /wp:group -->\n','Courses','','inherit','closed','closed','','9-revision-v1','','','2026-09-26 20:55:22','2026-09-26 15:25:22','',9,'http://localhost:8092/?p=126',0,'revision','',0),
